window.KOREAN_GRAMMAR_EXPLAINED = {"generatedAt":"2026-06-28T15:48:24.066Z","rawCount":255,"canonicalCount":249,"grammar":[{"id":"ko-explained-1","order":1,"bookLevel":1,"lesson":1,"lessonTitle":"소개","title":"입니다","category":"Ерөнхий","role":"нэр өгүүлэхүүн, албан ёсны хүүрнэх.","analogy":"Монгол хэлний “... юм”, “... байна”, заримдаа “... мөн” гэсэн өгүүлэхүүнтэй ойролцоо. Гэхдээ солонгост нэр үг өгүүлбэрийн төгсгөлд шууд ирэхгүй, заавал 입니다 / 이에요 зэрэг хэлбэрээр өгүүлбэр болдог.","structure":"N + 입니다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"저는 몽골 사람입니다.","exampleMn":"Би монгол хүн байна / Би монгол хүн.","caution":"학생입니다 гэж “оюутан байна” гэж ойлгоно; үгийг нэг бүрчлэн “оюутан юм байна” гэж орчуулах албагүй.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-2","order":2,"bookLevel":1,"lesson":1,"lessonTitle":"소개","title":"입니까","category":"Ерөнхий","role":"нэр өгүүлэхүүний албан асуулт.","analogy":"Монгол хэлний “... мөн үү?”, “... юу/юү?” гэсэн асуулттай адил үүрэгтэй.","structure":"N + 입니까?","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"선생님입니까?","exampleMn":"Та багш мөн үү?","caution":"Албан ёсны хэлбэр тул найздаа бол 이에요 ?/ 예요 ? илүү байгалийн.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-3","order":3,"bookLevel":1,"lesson":1,"lessonTitle":"소개","title":"은/는","category":"Ерөнхий","role":"сэдэв, харьцуулалт, мэдэгдэж буй зүйл.","analogy":"Монгол хэлний “бол”, “-ын хувьд”, “харин” гэсэн үүрэгтэй ойролцоо.","structure":"N + 은/는","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"저는 몽골 사람이고 친구는 한국 사람입니다.","exampleMn":"Би бол монгол хүн, харин найз маань солонгос хүн.","caution":"이 / 가 нь өгүүлэгдэхүүн, шинэ мэдээллийг заадаг; 은 / 는 нь тухайн зүйлийг сэдэв болгож ярьдаг.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-4","order":2,"bookLevel":1,"lesson":2,"lessonTitle":"학교","title":"여기/거기/저기","category":"Ерөнхий","role":"энэ/тэр/цаад газар.","analogy":"Монгол хэлний “энд/тэнд/цаана” тай адил.","structure":"여기/거기/저기 + 입니다/에/에서","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"여기가 도서관입니다.","exampleMn":"Энд номын сан байна.","caution":"여기 = миний ойр, 거기 = сонсогчийн ойр/өмнө дурдсан, 저기 = хоёулангаас хол.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-5","order":5,"bookLevel":1,"lesson":2,"lessonTitle":"학교","title":"이것/그것/저것","category":"Ерөнхий","role":"энэ/тэр/цаадах зүйл.","analogy":"Монгол хэлний “энэ/тэр/цаадах” тай адил.","structure":"이것/그것/저것 + 은/이","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"이것은 제 책입니다.","exampleMn":"Энэ бол миний ном.","caution":"이 / 그 / 저 нь зай болон ярианы нөхцөлөөр ялгарна.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-6","order":6,"bookLevel":1,"lesson":2,"lessonTitle":"학교","title":"이/가","category":"Ерөнхий","role":"өгүүлэгдэхүүн, шинэ/онцолсон мэдээлэл.","analogy":"Монгол хэлний өгүүлэгдэхүүнтэй дүйцнэ. Заримдаа “хэн/юу нь” гэсэн онцлолтой.","structure":"N + 이/가","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"비가 와요.","exampleMn":"Бороо орж байна.","caution":"Хэн хийсэн бэ? гэсэн шинэ мэдээлэлд 이 / 가 илүү тохиромжтой: 제가 했어요 - Би хийсэн.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-7","order":7,"bookLevel":1,"lesson":2,"lessonTitle":"학교","title":"에 있습니다","category":"Ерөнхий","role":"байршилд оршин байх.","analogy":"Монгол хэлний “-д байна” бүтэцтэй адил.","structure":"N(байршил) + 에 + N이/가 있습니다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"방에 책상이 있습니다.","exampleMn":"Өрөөнд ширээ байна.","caution":"있다 нь “байх/орших”; амьд ба амьгүй зүйлд хэрэглэж болно.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-8","order":8,"bookLevel":1,"lesson":2,"lessonTitle":"학교","title":"이/가 아닙니다","category":"Ерөнхий","role":"нэр үгийн үгүйсгэл.","analogy":"Монгол хэлний “... биш” гэсэн өгүүлэхүүнтэй адил.","structure":"N + 이/가 아닙니다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"저는 의사가 아닙니다.","exampleMn":"Би эмч биш.","caution":"Нэр үг үгүйсгэхэд 안 биш, 아니다 хэрэглэнэ.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-9","order":3,"bookLevel":1,"lesson":3,"lessonTitle":"일상생활","title":"ㅂ/습니다","category":"Ерөнхий","role":"албан ёсны хүүрнэх төгсгөл.","analogy":"Монгол хэлний албан найруулгын “... байна”, “...даг” төгсгөлтэй ойролцоо.","structure":"V/A + ㅂ니다/습니다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"한국어를 공부합니다.","exampleMn":"Солонгос хэл сурч байна.","caution":"Үйл үг эгшгээр төгсвөл - ㅂ니다 , гийгүүлэгчээр төгсвөл - 습니다 .","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-10","order":10,"bookLevel":1,"lesson":3,"lessonTitle":"일상생활","title":"ㅂ/습니까","category":"Ерөнхий","role":"албан ёсны асуух төгсгөл.","analogy":"Монгол хэлний “... уу/үү?”, “... вэ?” гэсэн албан асуулттай дүйцнэ.","structure":"V/A + ㅂ니까/습니까?","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"한국어를 공부합니까?","exampleMn":"Солонгос хэл сурдаг уу?","caution":"Хариуцагчийг хүндэтгэх, албан нөхцөлд хэрэглэнэ.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-11","order":11,"bookLevel":1,"lesson":3,"lessonTitle":"일상생활","title":"을/를","category":"Ерөнхий","role":"шууд тусагдахуун.","analogy":"Монгол хэлний заахын тийн ялгал “-ыг/-ийг/-г” тай ойролцоо.","structure":"N + 을/를","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"책을 읽어요.","exampleMn":"Номыг уншиж байна.","caution":"Ярианд орхигдож болно, гэхдээ сурах шатанд зөв тавьж сур.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-12","order":12,"bookLevel":1,"lesson":3,"lessonTitle":"일상생활","title":"에서","category":"Ерөнхий","role":"үйлдэл болох газар, гарал цэг.","analogy":"Монгол хэлний “-д/-т” боловч хөдөлгөөн/үйлдэл явагдаж буй талбар гэж ойлгоно.","structure":"N + 에서","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"도서관에서 공부해요.","exampleMn":"Номын санд хичээл хийдэг.","caution":"학교에 가요 = сургууль руу явна; 학교에서 공부해요 = сургууль дээр хичээл хийдэг.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-13","order":4,"bookLevel":1,"lesson":4,"lessonTitle":"날짜와 요일","title":"숫자","category":"Ерөнхий","role":"тоо хэлэх систем.","analogy":"Монгол хэлэнд нэг тооны системтэй боловч солонгост хятад гаралтай тоо ба уугуул солонгос тоо гэж хоёр системтэй.","structure":"일/이/삼..., 하나/둘/셋...","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"사과 세 개를 샀어요.","exampleMn":"Гурван алим авсан.","caution":"Цаг, нас, тоологч үгээс хамаарч тооны систем өөрчлөгдөнө.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-14","order":14,"bookLevel":1,"lesson":4,"lessonTitle":"날짜와 요일","title":"와/과","category":"Ерөнхий","role":"ба/болон, хамт.","analogy":"Монгол хэлний “ба/болон”, эсвэл “-тай/-тэй хамт” гэсэн үүрэгтэй.","structure":"N + 와/과","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"친구와 영화를 봤어요.","exampleMn":"Найзтайгаа кино үзсэн.","caution":"Гийгүүлэгчээр төгссөн нэр үгэнд 과 , эгшгээр төгсвөл 와 .","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-15","order":15,"bookLevel":1,"lesson":4,"lessonTitle":"날짜와 요일","title":"에","category":"Ерөнхий","role":"цаг, чиглэл, байршлын цэг.","analogy":"Монгол хэлний “-д/-т”, зарим үед “руу/лүү” гэсэн чиглэлтэй ойролцоо.","structure":"N + 에","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"아침 9시에 학교에 가요.","exampleMn":"Өглөө 9 цагт сургууль руу явна.","caution":"에서 нь үйлдэл болж буй газар; 에 нь очих цэг, цаг, орших байршил.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-16","order":5,"bookLevel":1,"lesson":5,"lessonTitle":"하루 일과","title":"한국어 수","category":"Ерөнхий","role":"уугуул солонгос тоо.","analogy":"Монгол хэлний тоо шиг нэрийн өмнө тоо тавих боловч тоологч үгтэй хамт хэрэглэнэ.","structure":"하나/둘/셋 + 단위 명사","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"친구 두 명을 만났어요.","exampleMn":"Хоёр найзтайгаа уулзсан.","caution":"하나 , 둘 , 셋 нь тоологчийн өмнө 한 , 두 , 세 болж хувирна.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-17","order":17,"bookLevel":1,"lesson":5,"lessonTitle":"하루 일과","title":"단위 명사","category":"Ерөнхий","role":"тоологч нэр.","analogy":"Монгол хэлний “ширхэг, хүн, аяга, нас” зэрэг тоолох нэгжтэй адил.","structure":"тоо + 단위 명사","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"책 한 권을 샀어요.","exampleMn":"Нэг ширхэг/нэг боть ном авсан.","caution":"Солонгост бараг бүх тоолол тусгай нэгжтэй: 명 , 개 , 권 , 잔 .","occurrences":2,"levels":[1],"stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-18","order":18,"bookLevel":1,"lesson":5,"lessonTitle":"하루 일과","title":"아/어요","category":"Ерөнхий","role":"өдөр тутмын эелдэг төгсгөл.","analogy":"Монгол хэлний энгийн эелдэг “... байна/даг/на” гэж орчуулж болно.","structure":"V/A + 아요/어요/해요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"집에 가요.","exampleMn":"Гэртээ явлаа / явдаг.","caution":"Цагийг ганцаараа илэрхийлэхгүй; утга нь нөхцлөөс хамаарч одоо/ерөнхий/ ирээдүй байж болно.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-19","order":19,"bookLevel":1,"lesson":5,"lessonTitle":"하루 일과","title":"에 가다","category":"Ерөнхий","role":"нарийн холбоос/төгсгөл.","analogy":"Монгол хэлний нөхцөл, холбоос, өгүүлбэрийн өнгө аясыг илэрхийлдэг хэсэгтэй адилтгаж ойлгоно.","structure":"ө мн ө х ү гийн т ө р ө лд тааруулж залгана","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"이 표현을 쓰면 문장의 관계가 분명해져요.","exampleMn":"Энэ хэлбэрийг хэрэглэвэл өгүүлбэрийн холбоо тодорхой болно.","caution":"Үгээр нь биш, өгүүлбэрт гүйцэтгэж буй үүргээр нь ойлгоно.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-20","order":20,"bookLevel":1,"lesson":5,"lessonTitle":"하루 일과","title":"안","category":"Ерөнхий","role":"богино үгүйсгэл.","analogy":"Монгол хэлний “үгүй/битгий/хийхгүй” гэсэн богино үгүйсгэлтэй ойролцоо.","structure":"안 + V/A","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"저는 커피를 안 마셔요.","exampleMn":"Би кофе уудаггүй.","caution":"Нэр үгийг үгүйсгэхэд 안 биш 아니다 хэрэглэнэ.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-21","order":6,"bookLevel":1,"lesson":6,"lessonTitle":"주말","title":"았/었-","category":"Ерөнхий","role":"өнгөрсөн цаг.","analogy":"Монгол хэлний “-сан/-сэн”, “-лаа/-лээ” тай ойролцоо.","structure":"V/A + 았/었어요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"어제 친구를 만났어요.","exampleMn":"Өчигдөр найзтайгаа уулзсан.","caution":"았 / 었 нь үгийн дунд орж дараа нь төгсгөл авна: 만났습니다 , 만났어요 .","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-22","order":22,"bookLevel":1,"lesson":6,"lessonTitle":"주말","title":"하고","category":"Ерөнхий","role":"ярианы ба/болон, хамт.","analogy":"Монгол хэлний “ба/болон”, “-тай/-тэй” тай ойролцоо.","structure":"N + 하고","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"빵하고 우유를 샀어요.","exampleMn":"Талх, сүү авсан.","caution":"와 / 과 -оос ярианы өнгөтэй.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-23","order":23,"bookLevel":1,"lesson":6,"lessonTitle":"주말","title":"(으)ㅂ시다","category":"Ерөнхий","role":"хамт хийх санал.","analogy":"Монгол хэлний “...цгаая”, “...я/е” тай адил.","structure":"V + (으)ㅂ시다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"같이 갑시다.","exampleMn":"Хамт явцгаая.","caution":"Дотно найздаа 가자 , албан/эелдэг үед 갑시다 .","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-24","order":7,"bookLevel":1,"lesson":6,"lessonTitle":"주말","title":"ㅡ 탈락","category":"Ерөнхий","role":"ㅡ эгшиг гээгдэх дүрэм.","analogy":"Монгол хэлэнд яг ижил зүйл байхгүй; солонгос үйл үгийн үндэс залгавартай нийлэхэд авианы өөрчлөлт гардаг гэж ойлгоно.","structure":"ㅡ т ө гсс ө н ү ндэс + 아/어 → ㅡ гээгдэнэ","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"바쁘다 → 바빠요.","exampleMn":"Завгүй байна.","caution":"Сүүлийн өмнөх эгшгийг харж 아 / 어 сонгоно.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-25","order":25,"bookLevel":1,"lesson":6,"lessonTitle":"주말","title":"은/는(대조)","category":"Эсрэгцэл","role":"эсрэгцүүлж харьцуулах сэдэв.","analogy":"Монгол хэлний “харин”, “бол” гэсэн харьцуулалтын үүрэгтэй.","structure":"N + 은/는","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “эсрэгцэл” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"커피는 마시지만 차는 안 마셔요.","exampleMn":"Кофе бол ууна, харин цай уудаггүй.","caution":"Зүгээр сэдэв тавихаас гадна хоёр зүйлийг ялгаж харьцуулж болно.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-26","order":26,"bookLevel":1,"lesson":6,"lessonTitle":"주말","title":"고 싶다","category":"Ерөнхий","role":"хүсэл.","analogy":"Монгол хэлний “...-маар байна”, “...-хыг хүсэж байна” тай адил.","structure":"V + 고 싶다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"한국에 가고 싶어요.","exampleMn":"Солонгос руу явмаар байна.","caution":"Гуравдагч хүний хүслийг хэлэхэд - 고 싶어하다 хэрэглэнэ.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-27","order":8,"bookLevel":1,"lesson":8,"lessonTitle":"음식","title":"겠-","category":"Таамаг/ажиглалт","role":"таамаг, шийдвэр, хүсэл, ирээдүйн өнгө.","analogy":"Монгол хэлний “-х байх”, “-я/е”, “бололтой” гэсэн утгатай ойролцоо.","structure":"V/A + 겠다/겠어요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “таамаг/ажиглалт” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"맛있겠어요.","exampleMn":"Амттай байх нь ээ.","caution":"항상 future биш; “ 잘 모르겠습니다 ” нь ирээдүй биш, эелдэг илэрхийлэл.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-28","order":28,"bookLevel":1,"lesson":8,"lessonTitle":"음식","title":"지 않다","category":"Ерөнхий","role":"урт үгүйсгэл.","analogy":"Монгол хэлний “...гүй”, “... биш” гэсэн үгүйсгэлтэй адил.","structure":"V/A + 지 않다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"오늘은 춥지 않아요.","exampleMn":"Өнөөдөр хүйтэн биш.","caution":"안 + V/A-тай ойролцоо боловч 지 않다 нь бичгийн/тод хэлбэр.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-29","order":29,"bookLevel":1,"lesson":8,"lessonTitle":"음식","title":"(으)세요","category":"Ерөнхий","role":"эелдэг хүсэлт/захирамж.","analogy":"Монгол хэлний “...-аарай”, “...-на уу” тай ойролцоо.","structure":"V + (으)세요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"여기에 앉으세요.","exampleMn":"Энд сууна уу.","caution":"Хэт шууд тушаал биш, эелдэг хүсэлт.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-30","order":9,"bookLevel":1,"lesson":9,"lessonTitle":"집","title":"(으)로","category":"Ерөнхий","role":"чиглэл, арга хэрэгсэл, материал, сонголт.","analogy":"Монгол хэлний “-аар/-ээр”, “руу/лүү”, “болгон” гэсэн нөхцөлтэй ойролцоо.","structure":"N + (으)로","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"버스로 회사에 가요.","exampleMn":"Автобусаар ажил руу явдаг.","caution":"로 / 으로 нь олон утгатай тул өгүүлбэрийн үйл үгтэй нь хамт ойлгоно.","occurrences":3,"levels":[1,3],"stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-31","order":31,"bookLevel":1,"lesson":9,"lessonTitle":"집","title":"(으)ㄹ래요","category":"Ерөнхий","role":"ярианы хүсэл/сонголт/санал.","analogy":"Монгол хэлний “...-маар байна уу?”, “...-я/е?” тай ойролцоо.","structure":"V + (으)ㄹ래요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"커피 마실래요?","exampleMn":"Кофе уумаар байна уу?","caution":"Дээд хүнтэй албан нөхцөлд хэрэглэхэд хэт ярианы өнгөтэй.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-32","order":32,"bookLevel":1,"lesson":9,"lessonTitle":"집","title":"도","category":"Ерөнхий","role":"ч бас, хүртэл.","analogy":"Монгол хэлний “ч”, “бас” гэсэн нэмэх утгатай.","structure":"N + 도","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"저도 가고 싶어요.","exampleMn":"Би ч бас явмаар байна.","caution":"이 / 가 , 은 / 는 , 을 / 를 -ийн оронд орж болно: 저도 , 책도 .","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-33","order":34,"bookLevel":1,"lesson":10,"lessonTitle":"가족","title":"께서","category":"Ерөнхий","role":"хүндэтгэлийн өгүүлэгдэхүүн.","analogy":"Монгол хэлэнд яг ийм нөхцөл байхгүй; “багш маань”, “эрхэм ...” гэж хүндэтгэн хэлэхтэй ойролцоо.","structure":"N(х ү ндэтгэх х ү н) + 께서","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"선생님께서 오십니다.","exampleMn":"Багш ирж байна.","caution":"이 / 가 -ийн хүндэтгэлийн хэлбэр.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-34","order":35,"bookLevel":1,"lesson":10,"lessonTitle":"가족","title":"(으)시-","category":"Ерөнхий","role":"хүндэтгэлийн залгавар.","analogy":"Монгол хэлний “Та”, “багш ирлээ” гэх хүндэтгэлийн найруулгатай ойролцоо.","structure":"V/A + (으)시 + т ө гсг ө л","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"할머니께서 주무세요.","exampleMn":"Эмээ унтаж байна.","caution":"Өөрийгөө хүндэтгэхэд хэрэглэдэггүй.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-35","order":11,"bookLevel":1,"lesson":11,"lessonTitle":"날씨","title":"고","category":"Ерөнхий","role":"үйл/шинжийг зэрэгцүүлэн холбох.","analogy":"Монгол хэлний “... бөгөөд”, “...-аад”, “мөн” гэсэн холбоостой ойролцоо.","structure":"V/A + 고","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"밥을 먹고 학교에 갔어요.","exampleMn":"Хоолоо идээд сургууль явсан.","caution":"Дараалал эсвэл зэрэгцэл байж болох тул өгүүлбэрийн утгаар ялгана.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-36","order":37,"bookLevel":1,"lesson":11,"lessonTitle":"날씨","title":"부터~까지","category":"Ерөнхий","role":"эхлэх ба дуусах хүрээ.","analogy":"Монгол хэлний “...-аас ... хүртэл” бүтэцтэй адил.","structure":"N + 부터 N + 까지","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"아침부터 저녁까지 일했어요.","exampleMn":"Өглөөнөөс орой хүртэл ажилласан.","caution":"Цаг хугацаанд 부터 ~ 까지 , газарт 에서 ~ 까지 элбэг.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-37","order":38,"bookLevel":1,"lesson":11,"lessonTitle":"날씨","title":"(으)ㄹ 거예요","category":"Таамаг/ажиглалт","role":"төлөвлөгөө, ирээдүйн таамаг.","analogy":"Монгол хэлний “...-на”, “...-х гэж байна”, “...-х байх” тай ойролцоо.","structure":"V + (으)ㄹ 거예요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “таамаг/ажиглалт” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"내일 비가 올 거예요.","exampleMn":"Маргааш бороо орох байх.","caution":"Цэвэр ирээдүйгээс гадна таамаг илэрхийлнэ.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-38","order":39,"bookLevel":1,"lesson":11,"lessonTitle":"날씨","title":"ㅂ 불규칙","category":"Ерөнхий","role":"ㅂ жигд бус хувирал.","analogy":"Монгол хэлний авианы зохицолтой төстэй боловч солонгост ㅂ ихэвчлэн 우 / 오 болж хувирна.","structure":"춥다 → 추워요, 돕다 → 도와요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"날씨가 추워요.","exampleMn":"Цаг агаар хүйтэн байна.","caution":"Бүх ㅂ төгссөн үг жигд бус биш: 입다 → 입어요 .","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-39","order":12,"bookLevel":1,"lesson":11,"lessonTitle":"날씨","title":"에게/한테/께","category":"Ерөнхий","role":"хүнд/амьтанд чиглэх, өгөх, хэлэх.","analogy":"Монгол хэлний “-д/-т”, “руу/лүү”, “-нд” тай ойролцоо.","structure":"N + 에게/한테/께","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"친구에게 편지를 보냈어요.","exampleMn":"Найздаа захиа илгээсэн.","caution":"께 нь хүндэтгэлтэй, 한테 нь ярианы, 에게 нь бичгийн/ерөнхий.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-40","order":41,"bookLevel":1,"lesson":11,"lessonTitle":"날씨","title":"지만","category":"Ерөнхий","role":"нарийн холбоос/төгсгөл.","analogy":"Монгол хэлний нөхцөл, холбоос, өгүүлбэрийн өнгө аясыг илэрхийлдэг хэсэгтэй адилтгаж ойлгоно.","structure":"ө мн ө х ү гийн т ө р ө лд тааруулж залгана","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"이 표현을 쓰면 문장의 관계가 분명해져요.","exampleMn":"Энэ хэлбэрийг хэрэглэвэл өгүүлбэрийн холбоо тодорхой болно.","caution":"Үгээр нь биш, өгүүлбэрт гүйцэтгэж буй үүргээр нь ойлгоно.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-41","order":42,"bookLevel":1,"lesson":11,"lessonTitle":"날씨","title":"(으)려고 하다","category":"Зорилго","role":"санаа, зорилго.","analogy":"Монгол хэлний “...-х гэж байна”, “...-хаар төлөвлөж байна” тай адил.","structure":"V + (으)려고 하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “зорилго” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"한국어를 배우려고 해요.","exampleMn":"Солонгос хэл сурах гэж байна.","caution":"Зорилго нь өгүүлэгчийн санаатай холбоотой.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-42","order":13,"bookLevel":1,"lesson":13,"lessonTitle":"생일","title":"아/어서","category":"Шалтгаан","role":"дараалал эсвэл шалтгаан.","analogy":"Монгол хэлний “...-аад/-ээд”, эсвэл “...-аас/-ээд” гэсэн утгатай.","structure":"V/A + 아/어서","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “шалтгаан” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"늦어서 택시를 탔어요.","exampleMn":"Хоцорсон болохоор такси барьсан.","caution":"Өнгөрсөн цагийг өмнөх хэсэгт ихэвчлэн давхар тавихгүй: 늦었어서 гэж биш 늦 어서 .","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-43","order":44,"bookLevel":1,"lesson":13,"lessonTitle":"생일","title":"(으)ㄹ까요","category":"Таамаг/ажиглалт","role":"санал, асуулт, таамаг.","analogy":"Монгол хэлний “...-х уу?”, “...-я/е?”, “болов уу?” тай ойролцоо.","structure":"V + (으)ㄹ까요?","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “таамаг/ажиглалт” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"창문을 열까요?","exampleMn":"Цонхоо онгойлгох уу?","caution":"Өөрөө хийх санал болон хамт шийдэх асуултад хэрэглэнэ.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-44","order":45,"bookLevel":1,"lesson":13,"lessonTitle":"생일","title":"못","category":"Боломж","role":"чадахгүй, боломжгүй.","analogy":"Монгол хэлний “чадахгүй”, “боломжгүйгээс ...-гүй” утгатай.","structure":"못 + V","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “боломж” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"몸이 아파서 학교에 못 갔어요.","exampleMn":"Бие өвдөөд сургуульдаа явж чадсангүй.","caution":"안 = өөрөө хийхгүй; 못 = нөхцөлөөс болж чадахгүй.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-45","order":14,"bookLevel":1,"lesson":14,"lessonTitle":"취미","title":"(으)ㄹ 수 있다/없다","category":"Боломж","role":"чадвар, боломж.","analogy":"Монгол хэлний “чадна/чадахгүй”, “боломжтой/боломжгүй” тай адил.","structure":"V + (으)ㄹ 수 있다/없다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “боломж” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"한국어로 말할 수 있어요.","exampleMn":"Солонгосоор ярьж чадна.","caution":"능력 болон боломж хоёрын аль аль нь байж болно.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-46","order":47,"bookLevel":1,"lesson":14,"lessonTitle":"취미","title":"기/-는 것","category":"Ерөнхий","role":"үйл үгийг нэршүүлэх.","analogy":"Монгол хэлний “...-х”, “...-х явдал”, “...-даг нь” тай ойролцоо.","structure":"V + 기 / V + 는 것","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"한국어를 배우는 것은 재미있어요.","exampleMn":"Солонгос хэл сурах нь сонирхолтой.","caution":"기 нь ерөнхий үйл, 는 것 нь тодорхой үйл явдлыг илүү амьд илэрхийлнэ.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-47","order":48,"bookLevel":1,"lesson":14,"lessonTitle":"취미","title":"ㄷ 불규칙","category":"Ерөнхий","role":"ㄷ жигд бус хувирал.","analogy":"Монгол хэлэнд яг ижилгүй; ㄷ зарим үйл үгэнд эгшгийн өмнө ㄹ болж хувирна.","structure":"듣다 → 들어요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"음악을 들어요.","exampleMn":"Хөгжим сонсож байна.","caution":"닫다 → 닫아요 зэрэг зарим нь жигд хувирна.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-48","order":15,"bookLevel":1,"lesson":14,"lessonTitle":"취미","title":"에서~까지","category":"Ерөнхий","role":"газрын эхлэл ба төгсгөл.","analogy":"Монгол хэлний “...-аас ... хүртэл” бүтэцтэй.","structure":"N(газар) + 에서 N(газар) + 까지","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"집에서 학교까지 걸어가요.","exampleMn":"Гэрээс сургууль хүртэл алхаж явдаг.","caution":"부터 ~ 까지 -тай төстэй боловч 에서 нь газар/гарал цэгт илүү тохирно.","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-49","order":51,"bookLevel":1,"lesson":14,"lessonTitle":"취미","title":"(으)러 가다","category":"Зорилго","role":"зорилгоор явах/ирэх.","analogy":"Монгол хэлний “...-хаар явна”, “...-х гэж очно” тай адил.","structure":"V + (으)러 가다/오다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “зорилго” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"점심을 먹으러 식당에 갔어요.","exampleMn":"Өдрийн хоол идэхээр хоолны газар явсан.","caution":"Зөвхөн хөдөлгөөний үйл үгтэй хэрэглэнэ: 가다 , 오다 , 다니다 . Дэвтэр 3","stage":"Анхан шат","source":"Explained MN Grammar"},{"id":"ko-explained-50","order":1,"bookLevel":3,"lesson":1,"lessonTitle":"학교생활","title":"밖에","category":"Ерөнхий","role":"зөвхөн, өөр байхгүй.","analogy":"Монгол хэлний “зөвхөн ... л”, “...-аас өөр” тай ойролцоо.","structure":"N + 밖에 + ү г ү йсгэл","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"천 원밖에 없어요.","exampleMn":"Надад мянган вон л байна.","caution":"Заавал үгүйсгэлтэй хамт хэрэглэнэ: 없다 , 모르다 , 못하다 .","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-51","order":53,"bookLevel":3,"lesson":1,"lessonTitle":"학교생활","title":"(이)라고 하다","category":"Ерөнхий","role":"нэрлэх, өөрийгөө/юмсыг гэж дууддаг.","analogy":"Монгол хэлний “... гэж нэрлэдэг/гэдэг” тай адил.","structure":"N + (이)라고 하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"저는 바야르라고 합니다.","exampleMn":"Намайг Баяр гэдэг.","caution":"Нэр үгтэй хэрэглэнэ; үйл үгтэй 다고 하다 .","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-52","order":54,"bookLevel":3,"lesson":1,"lessonTitle":"학교생활","title":"게 되다","category":"Ерөнхий","role":"өөрчлөгдөж тийм болох.","analogy":"Монгол хэлний “...-х болсон”, “... болж таарсан” тай адил.","structure":"V + 게 되다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"한국에서 살게 되었어요.","exampleMn":"Солонгост амьдрах болсон.","caution":"Өөрийн шууд санаанаас илүү нөхцөлөөр болсон өнгө.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-53","order":55,"bookLevel":3,"lesson":1,"lessonTitle":"학교생활","title":"(으)ㄹ 생각이다","category":"Ерөнхий","role":"бодол/төлөвлөгөө.","analogy":"Монгол хэлний “...-х бодолтой”, “...-хаар төлөвлөж байна” тай адил.","structure":"V + (으)ㄹ 생각이다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"졸업 후에 취직할 생각이에요.","exampleMn":"Төгсөөд ажилд орох бодолтой.","caution":"Хувийн төлөвлөгөө.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-54","order":2,"bookLevel":3,"lesson":2,"lessonTitle":"대인 관계","title":"는 길이다","category":"Ерөнхий","role":"явж байгаа замдаа.","analogy":"Монгол хэлний “...-хаар явж байна”, “...-аас/руу явах замдаа” тай ойролцоо.","structure":"V + 는 길이다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"학교에 가는 길이에요.","exampleMn":"Сургууль руу явж байна.","caution":"Зөвхөн хөдөлгөөнтэй холбоотой нөхцөлд хэрэглэнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-55","order":57,"bookLevel":3,"lesson":2,"lessonTitle":"대인 관계","title":"(으)ㄴ 덕분에","category":"Шалтгаан","role":"эерэг шалтгаан, ачаар.","analogy":"Монгол хэлний “...-ын ачаар” тай адил.","structure":"V/A + (으)ㄴ/는 덕분에, N 덕분에","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “шалтгаан” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"선생님 덕분에 많이 배웠어요.","exampleMn":"Багшийн ачаар их зүйл сурлаа.","caution":"Сөрөг үр дүнд 탓에 , 바람에 илүү тохирно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-56","order":58,"bookLevel":3,"lesson":2,"lessonTitle":"대인 관계","title":"나요?/-(으)ㄴ가요?","category":"Ерөнхий","role":"зөөлөн асуулт.","analogy":"Монгол хэлний “... болов уу?”, “... юу?” гэсэн зөөлөн асуулттай ойролцоо.","structure":"V + 나요?, A + (으)ㄴ가요?","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"지금 시간이 있나요?","exampleMn":"Одоо завтай юу?","caution":"Шууд - 습니까 ?-аас зөөлөн, эелдэг сонсогдоно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-57","order":3,"bookLevel":3,"lesson":3,"lessonTitle":"건강","title":"는 게 좋다","category":"Ерөнхий","role":"зөвлөгөө, санал.","analogy":"Монгол хэлний “...-сан нь дээр”, “...-вэл сайн” тай адил.","structure":"V + 는 게 좋다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"병원에 가는 게 좋아요.","exampleMn":"Эмнэлэгт очсон нь дээр.","caution":"Зөөлөн зөвлөгөө; тушаал биш.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-58","order":60,"bookLevel":3,"lesson":3,"lessonTitle":"건강","title":"아/어 보이다","category":"Ерөнхий","role":"харагдах байдал.","analogy":"Монгол хэлний “... харагдаж байна” тай адил.","structure":"A + 아/어 보이다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"오늘 피곤해 보여요.","exampleMn":"Өнөөдөр ядарсан харагдаж байна.","caution":"Өөрөө мэдэрсэн биш, гаднаас харсан сэтгэгдэл.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-59","order":61,"bookLevel":3,"lesson":3,"lessonTitle":"건강","title":"(으)ㄴ/는 것 같다","category":"Таамаг/ажиглалт","role":"таамаг, бололтой.","analogy":"Монгол хэлний “... юм шиг”, “... бололтой” тай адил.","structure":"A + (으)ㄴ 것 같다, V + 는 것 같다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “таамаг/ажиглалт” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"밖에 비가 오는 것 같아요.","exampleMn":"Гадаа бороо орж байгаа бололтой.","caution":"Шууд баттай хэлэхгүй, зөөлрүүлж таамаглана.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-60","order":4,"bookLevel":3,"lesson":4,"lessonTitle":"쇼핑","title":"대신(에)","category":"Ерөнхий","role":"оронд нь.","analogy":"Монгол хэлний “оронд нь” тай адил.","structure":"N + 대신(에)","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"제가 친구 대신에 갔어요.","exampleMn":"Би найзынхаа оронд явсан.","caution":"Нэр үгтэй шууд хэрэглэнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-61","order":63,"bookLevel":3,"lesson":4,"lessonTitle":"쇼핑","title":"(으)ㄴ/는 대신에","category":"Ерөнхий","role":"оронд нь, харин.","analogy":"Монгол хэлний “...-хын оронд”, “... оронд” тай адил.","structure":"V/A + (으)ㄴ/는 대신에","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"택시를 타는 대신에 걸어갔어요.","exampleMn":"Такси барихын оронд алхсан.","caution":"Сонголт солих буюу нөхөн орлуулах.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-62","order":64,"bookLevel":3,"lesson":4,"lessonTitle":"쇼핑","title":"기는 하다","category":"Эсрэгцэл","role":"хүлээн зөвшөөрөөд эсрэг өнгө нэмэх.","analogy":"Монгол хэлний “... бол ...”, “... нь үнэн л дээ” тай ойролцоо.","structure":"V/A + 기는 하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “эсрэгцэл” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"맛있기는 하지만 좀 비싸요.","exampleMn":"Амттай нь амттай, гэхдээ жаахан үнэтэй.","caution":"Дараагийн хэсэгт ихэвчлэн эсрэгцэл ирдэг.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-63","order":5,"bookLevel":3,"lesson":5,"lessonTitle":"요리","title":"고 나서","category":"Ерөнхий","role":"дараа нь.","analogy":"Монгол хэлний “...-сны дараа” тай адил.","structure":"V + 고 나서","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"밥을 먹고 나서 공부했어요.","exampleMn":"Хоолоо идсэний дараа хичээл хийсэн.","caution":"Үйл явдлын дараалал тодорхой үед хэрэглэнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-64","order":67,"bookLevel":3,"lesson":5,"lessonTitle":"요리","title":"다가","category":"Ерөнхий","role":"хийж байгаад өөр үйлдэлд шилжих.","analogy":"Монгол хэлний “...ж байгаад” тай ойролцоо.","structure":"V + 다가","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"길을 걷다가 친구를 만났어요.","exampleMn":"Алхаж байгаад найзтайгаа таарсан.","caution":"Эхний үйлдэл тасарч, дараагийн үйл явдал болсон.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-65","order":68,"bookLevel":3,"lesson":5,"lessonTitle":"요리","title":"게","category":"Ерөнхий","role":"байдлаар, үр дүнгийн хэлбэр.","analogy":"Монгол хэлний “...-аар/-ээр”, “... байхаар” гэсэн дайвар утгатай.","structure":"A + 게","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"문을 조용하게 닫으세요.","exampleMn":"Хаалгаа чимээгүй хаагаарай.","caution":"Тэмдэг үйлийг үйл үгийг тодотгох дайвар болгоно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-66","order":6,"bookLevel":3,"lesson":6,"lessonTitle":"은행","title":"기 쉽다","category":"Ерөнхий","role":"амархан тэгэх магадлалтай.","analogy":"Монгол хэлний “...-хад амар”, “...-х гээд байдаг” тай ойролцоо.","structure":"V + 기 쉽다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"겨울에는 감기에 걸리기 쉬워요.","exampleMn":"Өвөл ханиад хүрэхэд амархан.","caution":"Эерэг/сөрөг аль алинд хэрэглэгдэнэ, гэхдээ сөрөг боломжид их ашиглагддаг.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-67","order":70,"bookLevel":3,"lesson":6,"lessonTitle":"은행","title":"는 동안","category":"Ерөнхий","role":"хугацаанд.","analogy":"Монгол хэлний “... байх хугацаанд”, “... хооронд” тай адил.","structure":"V + 는 동안","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"제가 요리하는 동안 음악을 들으세요.","exampleMn":"Намайг хоол хийж байх хооронд хөгжим сонсоорой.","caution":"동안 өмнөх үйл явц үргэлжилж байх хугацааг заана.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-68","order":71,"bookLevel":3,"lesson":6,"lessonTitle":"은행","title":"(으)려면","category":"Нөхцөл","role":"нөхцөлтэй зорилго.","analogy":"Монгол хэлний “...-х гэвэл”, “...-хын тулд” тай ойролцоо.","structure":"V + (으)려면","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “нөхцөл” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"한국어를 잘하려면 매일 연습해야 해요.","exampleMn":"Солонгос хэлээ сайжруулах гэвэл өдөр бүр давтах хэрэгтэй.","caution":"Өмнөх хэсэг зорилго, дараах хэсэг хэрэгтэй нөхцөл.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-69","order":7,"bookLevel":3,"lesson":7,"lessonTitle":"성격","title":"처럼","category":"Ерөнхий","role":"шиг, мэт.","analogy":"Монгол хэлний “шиг”, “мэт” тай адил.","structure":"N + 처럼","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"아이처럼 웃어요.","exampleMn":"Хүүхэд шиг инээдэг.","caution":"비슷하다 / 같다 утгатай харьцуулалт.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-70","order":73,"bookLevel":3,"lesson":7,"lessonTitle":"성격","title":"군요","category":"Ерөнхий","role":"шинээр мэдээд гайхах/ойлгох.","analogy":"Монгол хэлний “... юм байна”, “... шүү дээ” тай ойролцоо.","structure":"V/A + 군요/는군요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"한국어를 정말 잘하시는군요.","exampleMn":"Солонгосоор үнэхээр сайн ярьдаг юм байна.","caution":"Өмнө мэдээгүй зүйлээ одоо анзаарсан өнгөтэй.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-71","order":74,"bookLevel":3,"lesson":7,"lessonTitle":"성격","title":"(으)ㄴ/는 편이다","category":"Ерөнхий","role":"нарийн холбоос/төгсгөл.","analogy":"Монгол хэлний нөхцөл, холбоос, өгүүлбэрийн өнгө аясыг илэрхийлдэг хэсэгтэй адилтгаж ойлгоно.","structure":"ө мн ө х ү гийн т ө р ө лд тааруулж залгана","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"이 표현을 쓰면 문장의 관계가 분명해져요.","exampleMn":"Энэ хэлбэрийг хэрэглэвэл өгүүлбэрийн холбоо тодорхой болно.","caution":"Үгээр нь биш, өгүүлбэрт гүйцэтгэж буй үүргээр нь ойлгоно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-72","order":8,"bookLevel":3,"lesson":8,"lessonTitle":"실수","title":"는 바람에","category":"Шалтгаан","role":"гэнэтийн сөрөг шалтгаан.","analogy":"Монгол хэлний “...-снаас болж”, “...-аас болоод” тай адил.","structure":"V + 는 바람에","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “шалтгаан” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"비가 오는 바람에 소풍이 취소됐어요.","exampleMn":"Бороо орсноос болж зугаалга цуцлагдсан.","caution":"Ихэвчлэн хүсээгүй, сөрөг үр дүнтэй.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-73","order":76,"bookLevel":3,"lesson":8,"lessonTitle":"실수","title":"는 중이다","category":"Ерөнхий","role":"хийж байх яг одоо/явц.","analogy":"Монгол хэлний “... хийж байна”, “... явцдаа байна” тай адил.","structure":"V + 는 중이다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"회의하는 중이에요.","exampleMn":"Хурал хийж байна.","caution":"Одоогийн үргэлжилж буй үйлдлийг тодотгоно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-74","order":77,"bookLevel":3,"lesson":8,"lessonTitle":"실수","title":"도록 하다","category":"Ерөнхий","role":"заавар/даалгах/зохицуулах.","analogy":"Монгол хэлний “...-аарай”, “...-хаар болго”, “...-уулах” тай ойролцоо.","structure":"V + 도록 하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"내일까지 제출하도록 하세요.","exampleMn":"Маргааш гэхэд өгөхөөр болгоорой.","caution":"Албан заавар, дүрэм, даалгаварт их хэрэглэнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-75","order":78,"bookLevel":3,"lesson":8,"lessonTitle":"실수","title":"(으)ㄴ/는/(으)ㄹ 줄 알다","category":"Ерөнхий","role":"нарийн холбоос/төгсгөл.","analogy":"Монгол хэлний нөхцөл, холбоос, өгүүлбэрийн өнгө аясыг илэрхийлдэг хэсэгтэй адилтгаж ойлгоно.","structure":"ө мн ө х ү гийн т ө р ө лд тааруулж залгана","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"이 표현을 쓰면 문장의 관계가 분명해져요.","exampleMn":"Энэ хэлбэрийг хэрэглэвэл өгүүлбэрийн холбоо тодорхой болно.","caution":"Үгээр нь биш, өгүүлбэрт гүйцэтгэж буй үүргээр нь ойлгоно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-76","order":9,"bookLevel":3,"lesson":9,"lessonTitle":"이사","title":"(으)ㄹ 줄 알다/모르다","category":"Ерөнхий","role":"нарийн холбоос/төгсгөл.","analogy":"Монгол хэлний нөхцөл, холбоос, өгүүлбэрийн өнгө аясыг илэрхийлдэг хэсэгтэй адилтгаж ойлгоно.","structure":"ө мн ө х ү гийн т ө р ө лд тааруулж залгана","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"이 표현을 쓰면 문장의 관계가 분명해져요.","exampleMn":"Энэ хэлбэрийг хэрэглэвэл өгүүлбэрийн холбоо тодорхой болно.","caution":"Үгээр нь биш, өгүүлбэрт гүйцэтгэж буй үүргээр нь ойлгоно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-77","order":80,"bookLevel":3,"lesson":9,"lessonTitle":"이사","title":"에 비해서","category":"Ерөнхий","role":"нарийн холбоос/төгсгөл.","analogy":"Монгол хэлний нөхцөл, холбоос, өгүүлбэрийн өнгө аясыг илэрхийлдэг хэсэгтэй адилтгаж ойлгоно.","structure":"ө мн ө х ү гийн т ө р ө лд тааруулж залгана","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"이 표현을 쓰면 문장의 관계가 분명해져요.","exampleMn":"Энэ хэлбэрийг хэрэглэвэл өгүүлбэрийн холбоо тодорхой болно.","caution":"Үгээр нь биш, өгүүлбэрт гүйцэтгэж буй үүргээр нь ойлгоно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-78","order":81,"bookLevel":3,"lesson":9,"lessonTitle":"이사","title":"기 바라다","category":"Ерөнхий","role":"нарийн холбоос/төгсгөл.","analogy":"Монгол хэлний нөхцөл, холбоос, өгүүлбэрийн өнгө аясыг илэрхийлдэг хэсэгтэй адилтгаж ойлгоно.","structure":"ө мн ө х ү гийн т ө р ө лд тааруулж залгана","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"이 표현을 쓰면 문장의 관계가 분명해져요.","exampleMn":"Энэ хэлбэрийг хэрэглэвэл өгүүлбэрийн холбоо тодорхой болно.","caution":"Үгээр нь биш, өгүүлбэрт гүйцэтгэж буй үүргээр нь ойлгоно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-79","order":82,"bookLevel":3,"lesson":9,"lessonTitle":"이사","title":"아무 (이)나","category":"Ерөнхий","role":"хэн/юу ч хамаагүй.","analogy":"Монгол хэлний “хэн ч”, “юу ч”, “ямар ч” тай ойролцоо.","structure":"아무 + N + (이)나","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"아무거나 괜찮아요.","exampleMn":"Юу ч байсан болно.","caution":"Сонголт чөлөөтэй, ялгаагүй.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-80","order":10,"bookLevel":3,"lesson":10,"lessonTitle":"여행","title":"다고 하다","category":"Дам яриа","role":"дам яриа: хүүрнэх.","analogy":"Монгол хэлний “... гэж хэлсэн/гэнэ” тай адил.","structure":"V/A + 다고 하다, N(이)라고 하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “дам яриа” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"친구가 내일 온다고 했어요.","exampleMn":"Найз маргааш ирнэ гэж хэлсэн.","caution":"Эх хүний хэлснийг шууд биш дам хэлж байна.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-81","order":84,"bookLevel":3,"lesson":10,"lessonTitle":"여행","title":"냐고 하다","category":"Дам яриа","role":"дам яриа: асуулт.","analogy":"Монгол хэлний “... гэж асуусан” тай адил.","structure":"V/A + 냐고 하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “дам яриа” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"선생님이 숙제를 했냐고 물었어요.","exampleMn":"Багш даалгавраа хийсэн үү гэж асуусан.","caution":"Асуултыг дамжуулахад хэрэглэнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-82","order":85,"bookLevel":3,"lesson":10,"lessonTitle":"여행","title":"(으)ㄹ까 하다","category":"Ерөнхий","role":"тэгэх үү гэж бодож байна.","analogy":"Монгол хэлний “...-х уу гэж бодож байна” тай адил.","structure":"V + (으)ㄹ까 하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"이번 주말에 쉴까 해요.","exampleMn":"Энэ амралтын өдөр амрах уу гэж бодож байна.","caution":"Шийдвэр бүрэн баттай биш.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-83","order":11,"bookLevel":3,"lesson":11,"lessonTitle":"고민","title":"반말","category":"Ерөнхий","role":"дотно, албан бус хэл.","analogy":"Монгол хэлний “чи” гэж дуудах дотно/шууд найруулгатай ойролцоо.","structure":"-아/어, -야, -자, -지 등","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"밥 먹었어?","exampleMn":"Хоолоо идсэн үү?","caution":"Нас, харилцаа, нөхцөл буруу бол бүдүүлэг сонсогдоно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-84","order":87,"bookLevel":3,"lesson":11,"lessonTitle":"고민","title":"아/야","category":"Нөхцөл","role":"дуудах нөхцөл, vocative.","analogy":"Монгол хэлний нэр дуудахад хэрэглэдэг “аа/ээ”, “Батаа!” тай ойролцоо.","structure":"이름 + 아/야","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “нөхцөл” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"민수야, 빨리 와.","exampleMn":"Минсү-яа, хурдан ир.","caution":"Гийгүүлэгчээр төгсвөл 아 , эгшгээр төгсвөл 야 .","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-85","order":88,"bookLevel":3,"lesson":11,"lessonTitle":"고민","title":"다(가) 보면","category":"Ерөнхий","role":"нарийн холбоос/төгсгөл.","analogy":"Монгол хэлний нөхцөл, холбоос, өгүүлбэрийн өнгө аясыг илэрхийлдэг хэсэгтэй адилтгаж ойлгоно.","structure":"ө мн ө х ү гийн т ө р ө лд тааруулж залгана","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"이 표현을 쓰면 문장의 관계가 분명해져요.","exampleMn":"Энэ хэлбэрийг хэрэглэвэл өгүүлбэрийн холбоо тодорхой болно.","caution":"Үгээр нь биш, өгүүлбэрт гүйцэтгэж буй үүргээр нь ойлгоно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-86","order":12,"bookLevel":3,"lesson":12,"lessonTitle":"인터넷","title":"(으)ㅁ","category":"Ерөнхий","role":"үйл үгийг нэр үг болгох бичгийн хэл.","analogy":"Монгол хэлний “...-х явдал”, “...-сан нь” тай ойролцоо.","structure":"V/A + (으)ㅁ","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"신청 기간이 끝났음을 알려 드립니다.","exampleMn":"Бүртгэлийн хугацаа дууссаныг мэдэгдэж байна.","caution":"Албан мэдэгдэл, бичгийн хэлэнд элбэг.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-87","order":90,"bookLevel":3,"lesson":12,"lessonTitle":"인터넷","title":"(으)라고 하다","category":"Дам яриа","role":"дам яриа: тушаал/заавар.","analogy":"Монгол хэлний “... гэж хэлсэн/тушаасан” тай ойролцоо.","structure":"V + (으)라고 하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “дам яриа” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"의사가 약을 먹으라고 했어요.","exampleMn":"Эмч эм уу гэж хэлсэн.","caution":"Хэн нэгний тушаал/зааврыг дамжуулна.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-88","order":91,"bookLevel":3,"lesson":12,"lessonTitle":"인터넷","title":"자고 하다","category":"Дам яриа","role":"дам яриа: санал.","analogy":"Монгол хэлний “...цгаая гэж хэлсэн” тай адил.","structure":"V + 자고 하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “дам яриа” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"친구가 같이 가자고 했어요.","exampleMn":"Найз хамт явъя гэж хэлсэн.","caution":"Хамт хийх саналыг дамжуулна.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-89","order":13,"bookLevel":3,"lesson":13,"lessonTitle":"희망","title":"아/어 가다","category":"Ерөнхий","role":"үйл явц цааш үргэлжлэх.","analogy":"Монгол хэлний “...-саар байх/явах” тай ойролцоо.","structure":"V/A + 아/어 가다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"한국어 실력이 좋아져 가요.","exampleMn":"Солонгос хэлний чадвар сайжирсаар байна.","caution":"Одоогоос ирээдүй рүү үргэлжлэх өөрчлөлт.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-90","order":93,"bookLevel":3,"lesson":13,"lessonTitle":"희망","title":"아/어 오다","category":"Ерөнхий","role":"өнгөрснөөс одоо хүртэл үргэлжлэх.","analogy":"Монгол хэлний “...-саар ирсэн” тай адил.","structure":"V/A + 아/어 오다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"오랫동안 한국어를 배워 왔어요.","exampleMn":"Удаан хугацаанд солонгос хэл сурсаар ирсэн.","caution":"Өнгөрсөн хугацааны үргэлжилсэн үйл явцыг онцолно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-91","order":94,"bookLevel":3,"lesson":13,"lessonTitle":"희망","title":"아/어야겠다","category":"Ерөнхий","role":"шийдвэр, хэрэгтэй гэж бодох.","analogy":"Монгол хэлний “...-х хэрэгтэй юм байна”, “...-я/е” тай ойролцоо.","structure":"V + 아/어야겠다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"이제 공부해야겠어요.","exampleMn":"Одоо хичээл хийх хэрэгтэй юм байна.","caution":"Өөрийн шийдвэр/ухаарал.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-92","order":95,"bookLevel":3,"lesson":13,"lessonTitle":"희망","title":"았/었으면 좋겠다","category":"Ерөнхий","role":"хүсэл, тийм болоосой.","analogy":"Монгол хэлний “... болоосой”, “...-вал сайнсан” тай адил.","structure":"V/A + 았/었으면 좋겠다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"내일 날씨가 좋았으면 좋겠어요.","exampleMn":"Маргааш цаг агаар сайхан байвал сайнсан.","caution":"Бодит болоогүй хүслийг илэрхийлнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-93","order":14,"bookLevel":3,"lesson":14,"lessonTitle":"영화와 드라마","title":"(아무리) -아/어도","category":"Ерөнхий","role":"хэчнээн ... ч.","analogy":"Монгол хэлний “хэчнээн ... ч” тай адил.","structure":"아무리 + V/A + 아/어도","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"아무리 바빠도 밥은 먹어야 해요.","exampleMn":"Хэчнээн завгүй байсан ч хоол идэх хэрэгтэй.","caution":"Хүчтэй эсрэг нөхцөл.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-94","order":97,"bookLevel":3,"lesson":14,"lessonTitle":"영화와 드라마","title":"거든(요)","category":"Ерөнхий","role":"тайлбар, учир нь.","analogy":"Монгол хэлний “... шүү дээ”, “учир нь ...” тай ойролцоо.","structure":"V/A + 거든요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"오늘은 좀 바쁘거든요.","exampleMn":"Өнөөдөр жаахан завгүй шүү дээ.","caution":"Өмнөх нөхцөл/асуултад шалтгаан тайлбарлана.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-95","order":98,"bookLevel":3,"lesson":14,"lessonTitle":"영화와 드라마","title":"던데요","category":"Таамаг/ажиглалт","role":"ажиглалтаар зөөлөн хэлэх.","analogy":"Монгол хэлний “... байсан шүү”, “... юм билээ” тай ойролцоо.","structure":"V/A + 던데요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “таамаг/ажиглалт” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"그 영화 재미있던데요.","exampleMn":"Тэр кино сонирхолтой байсан шүү.","caution":"Өөрийн ажиглалтаа зөөлөн дамжуулна.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-96","order":15,"bookLevel":3,"lesson":15,"lessonTitle":"예절과 규칙","title":"대로","category":"Ерөнхий","role":"дагуу, яг тэр хэвээр.","analogy":"Монгол хэлний “...-ын дагуу”, “...-аар нь” тай ойролцоо.","structure":"N + 대로 / V + 는 대로","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"말한 대로 하세요.","exampleMn":"Хэлсний дагуу хийгээрэй.","caution":"заавар, арга, төлөвлөгөө дагах үед хэрэглэнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-97","order":100,"bookLevel":3,"lesson":15,"lessonTitle":"예절과 규칙","title":"지 않으면 안 되다","category":"Ерөнхий","role":"заавал хийх шаардлага.","analogy":"Монгол хэлний “... хийхгүй бол болохгүй”, “заавал ... хэрэгтэй” тай адил.","structure":"V + 지 않으면 안 되다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"오늘 꼭 가야 해요. 안 가면 안 돼요.","exampleMn":"Өнөөдөр заавал явах хэрэгтэй. Явахгүй бол болохгүй.","caution":"Хоёр үгүйсгэл нийлээд хүчтэй шаардлага болно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-98","order":101,"bookLevel":3,"lesson":15,"lessonTitle":"예절과 규칙","title":"(으)려던 참이다","category":"Ерөнхий","role":"яг хийх гэж байсан.","analogy":"Монгол хэлний “яг ...-х гэж байсан” тай адил.","structure":"V + (으)려던 참이다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"지금 전화하려던 참이었어요.","exampleMn":"Одоо яг залгах гэж байсан юм.","caution":"Үйлдэл эхлэхийн өмнөх агшинг хэлнэ. Дэвтэр 4","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-99","order":1,"bookLevel":4,"lesson":1,"lessonTitle":"유행","title":"나 보다/-(으)ㄴ가 보다","category":"Ерөнхий","role":"харахад ... бололтой.","analogy":"Монгол хэлний “... бололтой”, “... юм шиг байна” тай ойролцоо.","structure":"V + 나 보다, A + (으)ㄴ가 보다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"사람이 많은 걸 보니 유명한가 봐요.","exampleMn":"Хүн их байгааг харахад алдартай бололтой.","caution":"Гаднын шинж тэмдэг дээр үндэслэсэн таамаг.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-100","order":103,"bookLevel":4,"lesson":1,"lessonTitle":"유행","title":"다고요?","category":"Ерөнхий","role":"давтан асууж гайхах.","analogy":"Монгол хэлний “... гэнээ?”, “... гэсэн үү?” тай ойролцоо.","structure":"V/A + 다고요?","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"벌써 끝났다고요?","exampleMn":"Аль хэдийн дууссан гэнээ?","caution":"Сонссон зүйлээ гайхаж дахин шалгана.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-101","order":104,"bookLevel":4,"lesson":1,"lessonTitle":"유행","title":"에 따라","category":"Ерөнхий","role":"даган, хамааран.","analogy":"Монгол хэлний “...-аас хамааран”, “... дагуу” тай адил.","structure":"N + 에 따라","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"계절에 따라 옷이 달라져요.","exampleMn":"Улирлаас хамааран хувцас өөрчлөгддөг.","caution":"Өөрчлөлтийн шалгуур/үндэс заана.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-102","order":2,"bookLevel":4,"lesson":2,"lessonTitle":"집안일","title":"잖아요","category":"Ерөнхий","role":"мэдэж байгаа шүү дээ.","analogy":"Монгол хэлний “... шүү дээ”, “... биз дээ” тай ойролцоо.","structure":"V/A + 잖아요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"오늘 시험이 있잖아요.","exampleMn":"Өнөөдөр шалгалттай шүү дээ.","caution":"Сонсогч мэдэж байгаа гэж үзсэн үед хэрэглэнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-103","order":106,"bookLevel":4,"lesson":2,"lessonTitle":"집안일","title":"자마자","category":"Ерөнхий","role":"магц.","analogy":"Монгол хэлний “...-магц/-мэгц”, “...-нгуут” тай адил.","structure":"V + 자마자","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"집에 오자마자 잤어요.","exampleMn":"Гэртээ ирмэгц унтсан.","caution":"Хоёр үйл явдал маш ойрхон дараалсан.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-104","order":107,"bookLevel":4,"lesson":2,"lessonTitle":"집안일","title":"사동사","category":"Ерөнхий","role":"үйлдүүлэх хэв.","analogy":"Монгол хэлний “явуулах, хийлгэх, унтуулах” зэрэг үйлдүүлэх хэвтэй адил.","structure":"идэвхг ү й/ ү йлд үү лэх ү гийн тусгай хэлбэр","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"엄마가 아이를 재웠어요.","exampleMn":"Ээж хүүхдээ унтуулсан.","caution":"Бүх үйл үг нэг ижил хувирдаггүй; үг бүрээр сурах шаардлагатай.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-105","order":108,"bookLevel":4,"lesson":2,"lessonTitle":"집안일","title":"게 하다","category":"Ерөнхий","role":"хийлгэх, болгох.","analogy":"Монгол хэлний үйлдүүлэх хэв “...-уулах/-үүлэх”, “...-лгах” тай ойролцоо.","structure":"V/A + 게 하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"선생님이 학생들에게 발표하게 했어요.","exampleMn":"Багш оюутнуудаар илтгэл хийлгэсэн.","caution":"Солонгосын аналитик causative; 사동사 -тай төстэй.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-106","order":3,"bookLevel":4,"lesson":3,"lessonTitle":"감정","title":"았/었었-","category":"Ерөнхий","role":"аль хэдийн өнгөрсөн туршлага/байдал.","analogy":"Монгол хэлний “тэгж байсан үе бий” гэсэн өнгөрсөн өнгөтэй.","structure":"V/A + 았/었었어요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"어릴 때는 부산에 살았었어요.","exampleMn":"Багадаа Пусанд амьдарч байсан.","caution":"Одоо тийм биш болсон өнгө тод илэрнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-107","order":110,"bookLevel":4,"lesson":3,"lessonTitle":"감정","title":"던","category":"Ерөнхий","role":"өнгөрсөнд давтагдсан/үргэлжилж байсан тодотгол.","analogy":"Монгол хэлний “... байсан”, “...даг байсан” тодотголтой ойролцоо.","structure":"V + 던 + N","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"제가 자주 가던 카페예요.","exampleMn":"Миний байнга очдог байсан кафе.","caution":"Өнгөрсөнд дуусаагүй/дадал байсан мэдрэмжтэй.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-108","order":111,"bookLevel":4,"lesson":3,"lessonTitle":"감정","title":"았/었던","category":"Ерөнхий","role":"өнгөрсөнд дууссан тодотгол.","analogy":"Монгол хэлний “...-сан байсан” тай ойролцоо.","structure":"V/A + 았/었던 + N","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"전에 만났던 사람이에요.","exampleMn":"Өмнө уулзаж байсан хүн.","caution":"던 -оос илүү дууссан өнгөрсөн үйл явдлыг хэлнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-109","order":112,"bookLevel":4,"lesson":3,"lessonTitle":"감정","title":"아/어하다","category":"Ерөнхий","role":"гуравдагч хүний мэдрэмжийг илэрхийлэх.","analogy":"Монгол хэлний “... гэж баярлах/дуртай байх/гуниглах” тай ойролцоо.","structure":"A + 아/어하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"아이가 무서워해요.","exampleMn":"Хүүхэд айж байна.","caution":"Өөрийн мэдрэмж: 저는 무서워요 ; бусдын мэдрэмж: 아이가 무서워해요 .","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-110","order":4,"bookLevel":4,"lesson":4,"lessonTitle":"생활 정보","title":"대요","category":"Дам яриа","role":"дам ярианы товчилсон хэлбэр.","analogy":"Монгол хэлний “... гэнэ/гэсэн” тай адил.","structure":"V/A + 대요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “дам яриа” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"내일 비가 온대요.","exampleMn":"Маргааш бороо орно гэнэ.","caution":"다고 해요 -ийн ярианы товчлол.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-111","order":114,"bookLevel":4,"lesson":4,"lessonTitle":"생활 정보","title":"냬요","category":"Ерөнхий","role":"дам асуултын товчлол.","analogy":"Монгол хэлний “... гэж асууж байна/асуусан” тай ойролцоо.","structure":"V/A + 냬요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"친구가 어디 가냬요.","exampleMn":"Найз хаашаа явах гэж байна гэж асууж байна.","caution":"냐고 해요 -ийн товчилсон хэлбэр.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-112","order":115,"bookLevel":4,"lesson":4,"lessonTitle":"생활 정보","title":"(으)래요","category":"Ерөнхий","role":"дам тушаалын товчлол.","analogy":"Монгол хэлний “... гэж байна/гэсэн” тай ойролцоо.","structure":"V + (으)래요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"선생님이 빨리 오래요.","exampleMn":"Багш хурдан ир гэж байна.","caution":"( 으 ) 라고 해요 -ийн товчилсон хэлбэр; мөн хүсэл - ㄹ래요 -тэй андуурч болохгүй.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-113","order":116,"bookLevel":4,"lesson":4,"lessonTitle":"생활 정보","title":"재요","category":"Ерөнхий","role":"дам саналын товчлол.","analogy":"Монгол хэлний “...цгаая гэж байна/гэсэн” тай адил.","structure":"V + 재요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"친구가 같이 먹재요.","exampleMn":"Найз хамт идье гэж байна.","caution":"자고 해요 -ийн товчилсон хэлбэр.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-114","order":5,"bookLevel":4,"lesson":5,"lessonTitle":"취직","title":"아/어야","category":"Нөхцөл","role":"заавал нөхцөл: ... байж.","analogy":"Монгол хэлний “... байж”, “...-вал л” тай ойролцоо.","structure":"V/A + 아/어야","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “нөхцөл” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"열심히 해야 성공할 수 있어요.","exampleMn":"Хичээж байж амжилтад хүрнэ.","caution":"Шаардлагатай нөхцөлийг заана.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-115","order":118,"bookLevel":4,"lesson":5,"lessonTitle":"취직","title":"아/어 놓다","category":"Ерөнхий","role":"урьдчилан хийж тавих.","analogy":"Монгол хэлний “...-чихээд тавих”, “урьдчилж ... хийх” тай ойролцоо.","structure":"V + 아/어 놓다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"회의 전에 자료를 준비해 놓았어요.","exampleMn":"Хурлын өмнө материалыг бэлдээд тавьсан.","caution":"Дараа хэрэглэхийн тулд бэлтгэсэн утгатай.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-116","order":119,"bookLevel":4,"lesson":5,"lessonTitle":"취직","title":"(으)ㄴ지 알다/모르다","category":"Ерөнхий","role":"мэдэх/мэдэхгүй: эсэх, хэр зэрэг.","analogy":"Монгол хэлний “... эсэхийг мэдэх/мэдэхгүй” тай адил.","structure":"V/A + (으)ㄴ/는지 알다/모르다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"언제 오는지 몰라요.","exampleMn":"Хэзээ ирэхийг мэдэхгүй.","caution":"Эргэлзээтэй мэдээллийг нэршүүлж мэдэх/асуухад хэрэглэнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-117","order":6,"bookLevel":4,"lesson":6,"lessonTitle":"고장","title":"피동사","category":"Ерөнхий","role":"үйлдэгдэх хэв.","analogy":"Монгол хэлний “-гдах/-дэх”, “хаалга онгойгдох” зэрэг үйлдэгдэх хэвтэй адил.","structure":"ү йлдэгдэх утгатай тусгай ү йл ү г","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"문이 열렸어요.","exampleMn":"Хаалга онгойсон/онгойгдсон.","caution":"Хэн хийснийг биш, үйлдэлд өртсөн зүйлийг гол болгоно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-118","order":121,"bookLevel":4,"lesson":6,"lessonTitle":"고장","title":"아/어지다","category":"Ерөнхий","role":"өөрчлөгдөх, үйлдэгдэх өнгө.","analogy":"Монгол хэлний “... болж өөрчлөгдөх”, заримдаа “...-гдах” утгатай.","structure":"A/V + 아/어지다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"날씨가 추워졌어요.","exampleMn":"Цаг агаар хүйтэрсэн.","caution":"Тэмдэг үгтэй бол өөрчлөлт, үйл үгтэй бол passive өнгө гарч болно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-119","order":122,"bookLevel":4,"lesson":6,"lessonTitle":"고장","title":"았/었을 때","category":"Ерөнхий","role":"нарийн холбоос/төгсгөл.","analogy":"Монгол хэлний нөхцөл, холбоос, өгүүлбэрийн өнгө аясыг илэрхийлдэг хэсэгтэй адилтгаж ойлгоно.","structure":"ө мн ө х ү гийн т ө р ө лд тааруулж залгана","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"이 표현을 쓰면 문장의 관계가 분명해져요.","exampleMn":"Энэ хэлбэрийг хэрэглэвэл өгүүлбэрийн холбоо тодорхой болно.","caution":"Үгээр нь биш, өгүүлбэрт гүйцэтгэж буй үүргээр нь ойлгоно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-120","order":7,"bookLevel":4,"lesson":7,"lessonTitle":"명절","title":"얼마나 -(으)ㄴ지","category":"Ерөнхий","role":"ямар их ... болохыг.","analogy":"Монгол хэлний “хэчнээн ... болохыг” тай адил.","structure":"얼마나 + A/V + (으)ㄴ/는지","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"얼마나 기쁜지 몰라요.","exampleMn":"Хэчнээн баяртай байгаагаа хэлж мэдэхгүй.","caution":"Сэтгэл хөдлөлийн хүчийг илэрхийлэхэд элбэг.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-121","order":124,"bookLevel":4,"lesson":7,"lessonTitle":"명절","title":"곤 하다","category":"Ерөнхий","role":"давтагддаг байсан/заншил.","analogy":"Монгол хэлний “...даг байлаа”, “...ж заншсан” тай ойролцоо.","structure":"V + 곤 하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"어릴 때 이 공원에서 놀곤 했어요.","exampleMn":"Багадаа энэ цэцэрлэгт тоглодог байлаа.","caution":"Өнгөрсөн дадалд их хэрэглэнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-122","order":125,"bookLevel":4,"lesson":7,"lessonTitle":"명절","title":"에다가","category":"Ерөнхий","role":"дээр нь нэмэх, байрлуулах.","analogy":"Монгол хэлний “дээр нь”, “-д нэмээд” тай ойролцоо.","structure":"N + 에다가","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"국에다가 소금을 넣으세요.","exampleMn":"Шөлөндөө давс хийгээрэй.","caution":"Байршил/нэмэлт оруулах утгатай.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-123","order":8,"bookLevel":4,"lesson":8,"lessonTitle":"여가 생활","title":"더라고(요)","category":"Ерөнхий","role":"өөрийн ажигласнаа хэлэх.","analogy":"Монгол хэлний “... байсан шүү”, “ажиглахад ... юм билээ” тай ойролцоо.","structure":"V/A + 더라고요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"그 식당 음식이 맛있더라고요.","exampleMn":"Тэр хоолны газрын хоол амттай байсан шүү.","caution":"Өөрийн туршлага/ажиглалтаас хэлнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-124","order":127,"bookLevel":4,"lesson":8,"lessonTitle":"여가 생활","title":"(이)야말로","category":"Ерөнхий","role":"жинхэнэ онцлол.","analogy":"Монгол хэлний “чухам ... л”, “жинхэнэ ...” тай адил.","structure":"N + (이)야말로","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"가족이야말로 가장 소중해요.","exampleMn":"Гэр бүл л хамгийн эрхэм.","caution":"Онцлон магтах, батлах үед хэрэглэнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-125","order":128,"bookLevel":4,"lesson":8,"lessonTitle":"여가 생활","title":"(으)ㄹ 만하다","category":"Ерөнхий","role":"хийхүйц, үнэ цэнэтэй.","analogy":"Монгол хэлний “...-хаар”, “...-чихээр”, “... үнэ цэнэтэй” тай ойролцоо.","structure":"V + (으)ㄹ 만하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"이 영화는 볼 만해요.","exampleMn":"Энэ кино үзчихээр кино байна.","caution":"Эерэг үнэлгээ эсвэл боломжийн хэмжээ заана.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-126","order":9,"bookLevel":4,"lesson":9,"lessonTitle":"직장","title":"(으)ㄹ 뿐만 아니라","category":"Ерөнхий","role":"төдийгүй.","analogy":"Монгол хэлний “... төдийгүй ...” тай адил.","structure":"V/A + (으)ㄹ 뿐만 아니라","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"그는 친절할 뿐만 아니라 실력도 좋아요.","exampleMn":"Тэр эелдэг төдийгүй чадвар ч сайн.","caution":"Хоёр сайн/муу шинжийг зэрэг нэмнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-127","order":130,"bookLevel":4,"lesson":9,"lessonTitle":"직장","title":"든지 -든지","category":"Ерөнхий","role":"аль нь ч.","analogy":"Монгол хэлний “... ч бай, ... ч бай” тай адил.","structure":"N/V + 든지 N/V + 든지","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"가든지 말든지 마음대로 하세요.","exampleMn":"Явсан ч, больсон ч өөрөө мэд.","caution":"Сонголт бүгд боломжтой/хамаагүй гэсэн өнгөтэй.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-128","order":131,"bookLevel":4,"lesson":9,"lessonTitle":"직장","title":"아/어 가지고","category":"Шалтгаан","role":"шалтгаан эсвэл дараалал, ярианы хэл.","analogy":"Монгол хэлний “...-аад/-ээд”, “... болохоор” тай ойролцоо.","structure":"V/A + 아/어 가지고","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “шалтгаан” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"늦게 일어나 가지고 택시를 탔어요.","exampleMn":"Орой босоод такси барьсан.","caution":"Ярианы хэл; албан бичигт - 아 / 어서 илүү тохиромжтой.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-129","order":10,"bookLevel":4,"lesson":10,"lessonTitle":"절약","title":"(으)ㄹ수록","category":"Ерөнхий","role":"хэдий чинээ ... төдий чинээ.","analogy":"Монгол хэлний “... тусам” тай адил.","structure":"V/A + (으)ㄹ수록","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"배울수록 재미있어요.","exampleMn":"Сурах тусам сонирхолтой.","caution":"Хоёр өөрчлөлт зэрэг өсөх/буурах холбоог заана.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-130","order":133,"bookLevel":4,"lesson":10,"lessonTitle":"절약","title":"(으)ㄴ/는 모양이다","category":"Ерөнхий","role":"харахад ... бололтой.","analogy":"Монгол хэлний “... бололтой”, “... шиг байна” тай ойролцоо.","structure":"A/V + (으)ㄴ/는 모양이다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"밖에 비가 오는 모양이에요.","exampleMn":"Гадаа бороо орж байгаа бололтой.","caution":"Нотолгоо/шинж тэмдэг дээр үндэслэнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-131","order":134,"bookLevel":4,"lesson":10,"lessonTitle":"절약","title":"느라고","category":"Ерөнхий","role":"нэг үйлдэлд анхаарч сөрөг үр дүн гарах.","analogy":"Монгол хэлний “... гэж байгаад”, “...-саар байгаад” тай ойролцоо.","structure":"V + 느라고","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"공부하느라고 전화를 못 받았어요.","exampleMn":"Хичээл хийж байгаад утсаа авч чадсангүй.","caution":"Ихэвчлэн сөрөг үр дүнтэй; санаатай үйлдэлтэй хэрэглэнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-132","order":11,"bookLevel":4,"lesson":11,"lessonTitle":"결혼","title":"다면","category":"Нөхцөл","role":"таамаг нөхцөл.","analogy":"Монгол хэлний “хэрэв ... бол” тай адил.","structure":"V/A + 다면","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “нөхцөл” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"돈이 많다면 세계 여행을 하고 싶어요.","exampleMn":"Мөнгө ихтэй байсан бол дэлхийгээр аялмаар байна.","caution":"Бодит биш эсвэл таамаг нөхцөлд их хэрэглэнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-133","order":136,"bookLevel":4,"lesson":11,"lessonTitle":"결혼","title":"(으)ㄹ 텐데","category":"Таамаг/ажиглалт","role":"таамаг + харамсал/санал.","analogy":"Монгол хэлний “... байх байсан”, “... юмсан” тай ойролцоо.","structure":"V/A + (으)ㄹ 텐데","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “таамаг/ажиглалт” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"바쁘실 텐데 와 주셔서 감사합니다.","exampleMn":"Завгүй байсан байх, ирсэнд баярлалаа.","caution":"Өгүүлэгчийн таамаг, санаа зовнил, харамсал илэрдэг.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-134","order":137,"bookLevel":4,"lesson":11,"lessonTitle":"결혼","title":"(으)ㄹ까 봐","category":"Зорилго","role":"болох вий гэж санаа зовох.","analogy":"Монгол хэлний “...чих вий гэж” тай адил.","structure":"V + (으)ㄹ까 봐","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “зорилго” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"늦을까 봐 택시를 탔어요.","exampleMn":"Хоцрох вий гэж такси барьсан.","caution":"Айдас/болгоомжлолын шалтгаан.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-135","order":12,"bookLevel":4,"lesson":12,"lessonTitle":"사건과 사고","title":"아/어 보니까","category":"Ерөнхий","role":"хийж үзтэл/харж байхад.","analogy":"Монгол хэлний “...ж үзтэл”, “...аад үзэхэд” тай ойролцоо.","structure":"V + 아/어 보니까","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"먹어 보니까 정말 맛있어요.","exampleMn":"Идэж үзтэл үнэхээр амттай байна.","caution":"Өөрийн туршлага дээр үндэслэсэн дүгнэлт.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-136","order":139,"bookLevel":4,"lesson":12,"lessonTitle":"사건과 사고","title":"(으)ㄹ 뻔하다","category":"Ерөнхий","role":"бараг тэгэх шахсан.","analogy":"Монгол хэлний “...-х шахсан”, “...-х дөхсөн” тай адил.","structure":"V + (으)ㄹ 뻔하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"버스를 놓칠 뻔했어요.","exampleMn":"Автобусаа алдах шахсан.","caution":"Ихэнхдээ болоогүй ч ойрхон байсан сөрөг үйл явдал.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-137","order":140,"bookLevel":4,"lesson":12,"lessonTitle":"사건과 사고","title":"아/어 있다","category":"Ерөнхий","role":"үйлдлийн үр дүн үргэлжилж байх.","analogy":"Монгол хэлний “...-сан хэвээр байна” тай адил.","structure":"V + 아/어 있다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"문이 열려 있어요.","exampleMn":"Хаалга онгорхой байна.","caution":"Үйлдэл дууссан ч үр дүн нь хадгалагдаж байна.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-138","order":13,"bookLevel":4,"lesson":13,"lessonTitle":"교육제도","title":"도록","category":"Зорилго","role":"зорилго, хэмжээ хүрэх хүртэл.","analogy":"Монгол хэлний “...-хаар”, “...-тлаа” тай ойролцоо.","structure":"V + 도록","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “зорилго” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"잘 들리도록 크게 말하세요.","exampleMn":"Сайн сонсогдохоор чанга яриарай.","caution":"Зорилго эсвэл үр дүнд хүрэх хэмжээг зааж болно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-139","order":142,"bookLevel":4,"lesson":13,"lessonTitle":"교육제도","title":"(으)ㄴ/는 데다가","category":"Ерөнхий","role":"дээрээс нь нэмээд.","analogy":"Монгол хэлний “тэгээд бас”, “дээрээс нь” тай адил.","structure":"A/V + (으)ㄴ/는 데다가","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"그 집은 넓은 데다가 교통도 편해요.","exampleMn":"Тэр байр өргөнөөс гадна унаа ч тухтай.","caution":"Нэг чиглэлийн шинжүүдийг нэмнэ.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-140","order":143,"bookLevel":4,"lesson":13,"lessonTitle":"교육제도","title":"(으)며","category":"Ерөнхий","role":"ба, мөн, зэрэг.","analogy":"Монгол хэлний “ба/болон”, бичгийн “мөн” тай ойролцоо.","structure":"V/A + (으)며","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"그는 성실하며 책임감이 강해요.","exampleMn":"Тэр нягт нямбай бөгөөд хариуцлагатай.","caution":"Бичгийн, албан найруулгад илүү элбэг.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-141","order":14,"bookLevel":4,"lesson":14,"lessonTitle":"생활과 환경","title":"(으)ㄴ/는 반면에","category":"Ерөнхий","role":"нөгөө талаар, харин.","analogy":"Монгол хэлний “харин”, “нөгөө талаас” тай адил.","structure":"A/V + (으)ㄴ/는 반면에","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"도시는 편리한 반면에 복잡해요.","exampleMn":"Хот тухтай боловч нөгөө талаар төвөгтэй.","caution":"Эсрэг хоёр шинжийг харьцуулна.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-142","order":145,"bookLevel":4,"lesson":14,"lessonTitle":"생활과 환경","title":"(으)ㄹ 정도이다","category":"Ерөнхий","role":"тийм хэмжээнд.","analogy":"Монгол хэлний “...-х хэмжээний”, “тэгтлээ” тай ойролцоо.","structure":"V/A + (으)ㄹ 정도이다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"눈물이 날 정도로 감동했어요.","exampleMn":"Нулимс гарахаар их сэтгэл хөдөлсөн.","caution":"Хэмжээ/түвшинг онцолно.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-143","order":146,"bookLevel":4,"lesson":14,"lessonTitle":"생활과 환경","title":"에 따르면","category":"Ерөнхий","role":"эх сурвалжийн дагуу.","analogy":"Монгол хэлний “...-ийн мэдээлснээр”, “...-ын дагуу” тай адил.","structure":"N + 에 따르면","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"뉴스에 따르면 내일 비가 온대요.","exampleMn":"Мэдээгээр маргааш бороо орно гэж байна.","caution":"Эх сурвалж заах бичгийн хэлбэр.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-144","order":15,"bookLevel":4,"lesson":15,"lessonTitle":"옛날이야기","title":"자","category":"Ерөнхий","role":"даруй/магц; мөн саналын энгийн хэлбэр байж болно.","analogy":"Монгол хэлний “...-магц” эсвэл “...я/е” тай ойролцоо.","structure":"V + 자","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"문을 열자 바람이 들어왔어요.","exampleMn":"Хаалга онгойлгомогц салхи орж ирсэн.","caution":"Саналын 가자 -тай андуурахгүй; энд холбоосын 자 .","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-145","order":148,"bookLevel":4,"lesson":15,"lessonTitle":"옛날이야기","title":"다 보니까","category":"Ерөнхий","role":"хийсээр байгаад анзаарах.","analogy":"Монгол хэлний “...ж байтал”, “...саар байгаад” тай ойролцоо.","structure":"V + 다 보니까","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"한국어를 배우다 보니까 한국 문화도 알게 됐어요.","exampleMn":"Солонгос хэл сурсаар байгаад соёлыг нь мэддэг болсон.","caution":"Үйл явцын дундаас үр дүн/ойлголт гарсан.","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-146","order":149,"bookLevel":4,"lesson":15,"lessonTitle":"옛날이야기","title":"(으)ㄴ/는 척하다","category":"Ерөнхий","role":"дүр эсгэх.","analogy":"Монгол хэлний “... дүр үзүүлэх”, “... мэт жүжиглэх” тай адил.","structure":"V/A + (으)ㄴ/는 척하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"모르는 척했어요.","exampleMn":"Мэдэхгүй дүр эсгэсэн.","caution":"Үнэндээ тийм биш боловч тийм мэт аашлах. Дэвтэр 5","stage":"Дунд шат","source":"Explained MN Grammar"},{"id":"ko-explained-147","order":1,"bookLevel":5,"lesson":1,"lessonTitle":"만남과 교류","title":"게(연결어미)","category":"Ерөнхий","role":"үр дүн/байдал үүсгэх холбоос.","analogy":"Монгол хэлний “...-аар”, “... байхаар” тай ойролцоо.","structure":"A/V + 게","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"모두 들을 수 있게 크게 말했어요.","exampleMn":"Бүгд сонсож чадахаар чанга ярьсан.","caution":"Дараах үйлдлийн байдал, зорилго, үр дүнг тодорхойлно.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-148","order":151,"bookLevel":5,"lesson":1,"lessonTitle":"만남과 교류","title":"(으)ㄹ걸","category":"Ерөнхий","role":"харамсал: тэгэх байсан юм.","analogy":"Монгол хэлний “...даг байж”, “...х байсан юм” тай ойролцоо.","structure":"V/A + (으)ㄹ걸","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"좀 더 일찍 올걸.","exampleMn":"Арай эрт ирдэг байж.","caution":"Өнгөрсөнд өөрөөр хийх байсан гэсэн харамсал.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-149","order":152,"bookLevel":5,"lesson":1,"lessonTitle":"만남과 교류","title":"(으)로 인해","category":"Шалтгаан","role":"шалтгаан, улмаас.","analogy":"Монгол хэлний “...-ын улмаас”, “...-аас болж” тай адил.","structure":"N + (으)로 인해","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “шалтгаан” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"폭설로 인해 길이 막혔어요.","exampleMn":"Их цасны улмаас зам хаагдсан.","caution":"Албан/бичгийн хэлэнд элбэг.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-150","order":2,"bookLevel":5,"lesson":2,"lessonTitle":"서울","title":"(으)ㄴ/는 만큼","category":"Шалтгаан","role":"хэмжээ/шалтгаан: ... хэрээр, учраас.","analogy":"Монгол хэлний “... хэрээр”, “... болохоор” тай ойролцоо.","structure":"A/V + (으)ㄴ/는 만큼","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “шалтгаан” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"열심히 공부한 만큼 결과가 좋을 거예요.","exampleMn":"Хичээсэн хэрээр үр дүн сайн байх болно.","caution":"Хэмжээ, үндэслэл хоёрын аль алинд хэрэглэгдэнэ.","occurrences":2,"levels":[5,6],"stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-151","order":154,"bookLevel":5,"lesson":2,"lessonTitle":"서울","title":"(으)ㄹ 뿐이다","category":"Ерөнхий","role":"зөвхөн ... л.","analogy":"Монгол хэлний “зөвхөн ... л”, “... төдий” тай адил.","structure":"V/A + (으)ㄹ 뿐이다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"저는 사실을 말했을 뿐이에요.","exampleMn":"Би зөвхөн үнэнийг хэлсэн төдий.","caution":"Өөр зүйл байхгүй, хязгаарлах утга.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-152","order":155,"bookLevel":5,"lesson":2,"lessonTitle":"서울","title":"(으)로서","category":"Ерөнхий","role":"байр суурь, чанарын хувьд.","analogy":"Монгол хэлний “...-ын хувьд”, “... болохын хувьд” тай адил.","structure":"N + (으)로서","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"교사로서 책임이 있어요.","exampleMn":"Багшийн хувьд хариуцлага бий.","caution":"( 으 ) 로써 = арга хэрэгсэл; ( 으 ) 로서 = байр суурь.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-153","order":3,"bookLevel":5,"lesson":3,"lessonTitle":"현대인의 건강","title":"(으)ㄴ 채로","category":"Ерөнхий","role":"тэр хэвээр.","analogy":"Монгол хэлний “... хэвээр”, “...-тай чигээрээ” тай адил.","structure":"V + (으)ㄴ 채로","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"불을 켠 채로 잠들었어요.","exampleMn":"Гэрлээ асаалттай чигээрээ унтсан.","caution":"Үйлдлийн байдал өөрчлөгдөөгүй хадгалагдсан.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-154","order":157,"bookLevel":5,"lesson":3,"lessonTitle":"현대인의 건강","title":"(으)ㄹ 수밖에 없다","category":"Ерөнхий","role":"өөр аргагүй.","analogy":"Монгол хэлний “...-хаас өөр аргагүй”, “...-х л болно” тай адил.","structure":"V + (으)ㄹ 수밖에 없다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"시간이 없어서 택시를 탈 수밖에 없어요.","exampleMn":"Цаг байхгүй тул такси барихаас өөр аргагүй.","caution":"밖에 + 없다 нь “өөр сонголт байхгүй” гэсэн хүчтэй утга.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-155","order":158,"bookLevel":5,"lesson":3,"lessonTitle":"현대인의 건강","title":"되","category":"Нөхцөл","role":"эсрэг нөхцөлтэй зөвшөөрөл.","analogy":"Монгол хэлний “... боловч”, “... гэхдээ” тай ойролцоо.","structure":"A/V + 되","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “нөхцөл” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"가도 되지만 늦지 마세요.","exampleMn":"Явж болно, гэхдээ битгий хоцроорой.","caution":"Албан бичиг, зааварт их харагдана.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-156","order":4,"bookLevel":5,"lesson":4,"lessonTitle":"사회와 봉사","title":"아/어다가","category":"Ерөнхий","role":"хийж аваад дараагийн үйлдэлд ашиглах.","analogy":"Монгол хэлний “...аад аваад”, “...ж ирээд” тай ойролцоо.","structure":"V + 아/어다가","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"물을 떠다가 꽃에 줬어요.","exampleMn":"Ус авчраад цэцэгт өгсөн.","caution":"Эхний үйлдлийн үр дүнг дараагийн үйлдэлд ашиглана.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-157","order":160,"bookLevel":5,"lesson":4,"lessonTitle":"사회와 봉사","title":"았/었더니","category":"Ерөнхий","role":"тэгтэл, үр дүн ажиглагдах.","analogy":"Монгол хэлний “...тэгтэл”, “...сан чинь” тай ойролцоо.","structure":"V + 았/었더니","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"약을 먹었더니 괜찮아졌어요.","exampleMn":"Эм уусан чинь дээрдсэн.","caution":"Өөрийн хийсэн/мэдэрсэн зүйлээс гарсан үр дүн.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-158","order":161,"bookLevel":5,"lesson":4,"lessonTitle":"사회와 봉사","title":"자면","category":"Ерөнхий","role":"... гэж хэлбэл/зорьё гэвэл.","analogy":"Монгол хэлний “... гэвэл”, “... гэж хэлэхэд” тай ойролцоо.","structure":"V + 자면","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"쉽게 말하자면 이건 기회예요.","exampleMn":"Энгийнээр хэлбэл энэ бол боломж.","caution":"тайлбарлах, тодруулах үед хэрэглэнэ.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-159","order":5,"bookLevel":5,"lesson":5,"lessonTitle":"뉴스와 신문","title":"고 말다","category":"Ерөнхий","role":"эцэст нь тэгж дуусах, харамсал.","analogy":"Монгол хэлний “...-чихлээ”, “эцэст нь ... боллоо” тай ойролцоо.","structure":"V + 고 말다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"결국 실패하고 말았어요.","exampleMn":"Эцэст нь бүтэлгүйтчихлээ.","caution":"Санаандгүй/хүсээгүй дуусалт ихтэй.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-160","order":163,"bookLevel":5,"lesson":5,"lessonTitle":"뉴스와 신문","title":"ㄴ다지요?","category":"Ерөнхий","role":"сонссон мэдээллээ батлах асуулт.","analogy":"Монгол хэлний “... гэдэг биз дээ?”, “... гэсэн үү?” тай ойролцоо.","structure":"V/A + ㄴ/는다지요?","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"그분이 유명한 의사라지요?","exampleMn":"Тэр хүн алдартай эмч гэсэн биз дээ?","caution":"Сонссон мэдээллээ шалгах өнгө.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-161","order":164,"bookLevel":5,"lesson":5,"lessonTitle":"뉴스와 신문","title":"는 한","category":"Ерөнхий","role":"... байгаа цагт.","analogy":"Монгол хэлний “... л бол”, “... байгаа цагт” тай адил.","structure":"V + 는 한","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"노력하는 한 성공할 수 있어요.","exampleMn":"Хичээж байгаа цагт амжилтад хүрч чадна.","caution":"Нөхцөл үргэлжилбэл үр дүн ч боломжтой.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-162","order":6,"bookLevel":5,"lesson":6,"lessonTitle":"역사 속의 인물","title":"다시피","category":"Ерөнхий","role":"... шиг, мэдэж байгаа шиг.","analogy":"Монгол хэлний “... шиг”, “... гэдгийг мэдэж байгаа” тай ойролцоо.","structure":"V + 다시피","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"보시다시피 상황이 어렵습니다.","exampleMn":"Таны харж байгаачлан нөхцөл хүнд байна.","caution":"Сонсогч мэдэж/харж буй зүйлийг суурь болгоно.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-163","order":166,"bookLevel":5,"lesson":6,"lessonTitle":"역사 속의 인물","title":"(으)ㅁ으로써","category":"Ерөнхий","role":"арга хэрэгслээр.","analogy":"Монгол хэлний “...-снаар”, “...-аар дамжуулан” тай адил.","structure":"V + (으)ㅁ으로써","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"꾸준히 연습함으로써 실력이 늘었어요.","exampleMn":"Тогтмол давтсанаар чадвар сайжирсан.","caution":"( 으 ) 로서 байр суурь; ( 으 ) 로써 арга хэрэгсэл.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-164","order":167,"bookLevel":5,"lesson":6,"lessonTitle":"역사 속의 인물","title":"이며","category":"Ерөнхий","role":"мөн, ба.","analogy":"Монгол хэлний “мөн”, “ба/болон” тай ойролцоо.","structure":"N + 이며/며","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"그는 의사이며 교수입니다.","exampleMn":"Тэр эмч бөгөөд профессор.","caution":"Бичгийн, жагсаах өнгөтэй.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-165","order":168,"bookLevel":5,"lesson":6,"lessonTitle":"역사 속의 인물","title":"았/었더라면","category":"Нөхцөл","role":"өнгөрсөн эсрэг нөхцөл.","analogy":"Монгол хэлний “...-сан бол ... байх байсан” тай адил.","structure":"V/A + 았/었더라면","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “нөхцөл” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"조금 일찍 출발했더라면 늦지 않았을 거예요.","exampleMn":"Арай эрт гарсан бол хоцрохгүй байсан.","caution":"Болоогүй өнгөрсөн нөхцөлийг төсөөлнө.","occurrences":2,"levels":[5,6],"stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-166","order":7,"bookLevel":5,"lesson":7,"lessonTitle":"속담과 관용표현","title":"(ㄴ/는)다고","category":"Дам яриа","role":"дам яриа эсвэл ишлэл.","analogy":"Монгол хэлний “... гэж” тай адил.","structure":"V/A + ㄴ/는다고","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “дам яриа” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"그가 곧 온다고 들었어요.","exampleMn":"Тэр удахгүй ирнэ гэж сонссон.","caution":"Дараа нь 하다 , 듣다 , 믿다 зэрэг үг ирж болно.","occurrences":2,"levels":[5,6],"stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-167","order":170,"bookLevel":5,"lesson":7,"lessonTitle":"속담과 관용표현","title":"(으)ㄴ/는 법이다","category":"Ерөнхий","role":"ердийн зүй тогтол.","analogy":"Монгол хэлний “... байдаг жамтай”, “ер нь ... байдаг” тай ойролцоо.","structure":"V/A + (으)ㄴ/는 법이다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"실수하면서 배우는 법이에요.","exampleMn":"Алдаж байж сурдаг жамтай.","caution":"Ерөнхий үнэн, зүй тогтлыг хэлнэ.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-168","order":171,"bookLevel":5,"lesson":7,"lessonTitle":"속담과 관용표현","title":"(으)ㄴ/는 듯이","category":"Ерөнхий","role":"... мэт, шиг.","analogy":"Монгол хэлний “шиг”, “мэт” тай адил.","structure":"V/A + (으)ㄴ/는 듯이","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"아무 일도 없는 듯이 행동했어요.","exampleMn":"Юу ч болоогүй мэт аашилсан.","caution":"Бодит эсэх нь тодорхой биш дүрслэл.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-169","order":8,"bookLevel":5,"lesson":8,"lessonTitle":"광고","title":"(으)ㄹ 테니까","category":"Ерөнхий","role":"би/энэ ... байх тул, тиймээс.","analogy":"Монгол хэлний “... болохоор”, “... тул” тай ойролцоо.","structure":"V/A + (으)ㄹ 테니까","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"제가 도와드릴 테니까 걱정하지 마세요.","exampleMn":"Би туслах болохоор битгий санаа зов.","caution":"Өгүүлэгчийн санаа/таамаг дээр тулгуурлан дараах зөвлөгөө/хүсэлт ирдэг.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-170","order":173,"bookLevel":5,"lesson":8,"lessonTitle":"광고","title":"(으)ㄴ/는가 하면","category":"Ерөнхий","role":"нэг талаар ... нөгөө талаар.","analogy":"Монгол хэлний “... байхад, бас ...” тай ойролцоо.","structure":"A/V + (으)ㄴ/는가 하면","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"그는 노래를 잘하는가 하면 춤도 잘 춰요.","exampleMn":"Тэр дуу сайн дуулахаас гадна бүжиг ч сайн хийдэг.","caution":"Хоёр өөр шинж/үйлдлийг зэрэгцүүлнэ.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-171","order":174,"bookLevel":5,"lesson":8,"lessonTitle":"광고","title":"(ㄴ/는)단/란 말이에요?","category":"Ерөнхий","role":"гайхаж баталгаажуулах.","analogy":"Монгол хэлний “... гэсэн үг үү?”, “... гэж үү?” тай ойролцоо.","structure":"V/A + ㄴ/는단 말이에요?","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"지금 떠난단 말이에요?","exampleMn":"Одоо явна гэсэн үг үү?","caution":"Гайхах, итгэхгүй байх өнгөтэй.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-172","order":9,"bookLevel":5,"lesson":9,"lessonTitle":"생활의 변화와 주거","title":"(이)라도","category":"Ерөнхий","role":"ядаж, гэх мэтээс нэг.","analogy":"Монгол хэлний “ядаж ... ч болов”, “... ч гэсэн” тай ойролцоо.","structure":"N + (이)라도","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"시간이 없으면 커피라도 마셔요.","exampleMn":"Цаг байхгүй бол ядаж кофе ч болов уу.","caution":"Хамгийн сайн сонголт биш ч боломжит сонголт.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-173","order":176,"bookLevel":5,"lesson":9,"lessonTitle":"생활의 변화와 주거","title":"는 통에","category":"Шалтгаан","role":"сөрөг шалтгаан, завгүй/үймээнээс болж.","analogy":"Монгол хэлний “...-снаас болж”, “... үймээнээр” тай ойролцоо.","structure":"V + 는 통에","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “шалтгаан” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"아이들이 떠드는 통에 잠을 못 잤어요.","exampleMn":"Хүүхдүүд шуугиснаас болж унтаж чадсангүй.","caution":"Сөрөг үр дүнтэй, ярианы өнгөтэй.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-174","order":177,"bookLevel":5,"lesson":9,"lessonTitle":"생활의 변화와 주거","title":"기에","category":"Шалтгаан","role":"шалтгаан/үндэслэл, бичгийн хэл.","analogy":"Монгол хэлний “... тул”, “... учир” тай ойролцоо.","structure":"V/A + 기에","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “шалтгаан” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"날씨가 좋기에 산책을 했어요.","exampleMn":"Цаг агаар сайхан байсан тул салхилсан.","caution":"Бичгийн/арай албан хэлбэр.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-175","order":10,"bookLevel":5,"lesson":10,"lessonTitle":"대중문화","title":"더니","category":"Ерөнхий","role":"ажигласан өөрчлөлт/үр дүн.","analogy":"Монгол хэлний “...тэгсэн чинь”, “...даг байсан, одоо ...” тай ойролцоо.","structure":"V/A + 더니","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"아침에는 비가 오더니 지금은 맑아요.","exampleMn":"Өглөө бороо орж байсан, харин одоо цэлмэг байна.","caution":"Өмнөх ажиглалт ба дараах өөрчлөлтийг холбодог.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-176","order":179,"bookLevel":5,"lesson":10,"lessonTitle":"대중문화","title":"(으)ㄹ걸요","category":"Таамаг/ажиглалт","role":"зөөлөн таамаг.","analogy":"Монгол хэлний “... байх шүү”, “... байх даа” тай ойролцоо.","structure":"V/A + (으)ㄹ걸요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “таамаг/ажиглалт” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"아마 집에 있을걸요.","exampleMn":"Магадгүй гэртээ байгаа байх шүү.","caution":"Баттай биш, зөөлөн таамаг.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-177","order":180,"bookLevel":5,"lesson":10,"lessonTitle":"대중문화","title":"아/어 버리다","category":"Ерөнхий","role":"бүрэн дуусгах, харамсах/хөнгөвчлөх өнгө.","analogy":"Монгол хэлний “...-чихлээ” тай маш ойролцоо.","structure":"V + 아/어 버리다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"지갑을 잃어버렸어요.","exampleMn":"Түрийвчээ гээчихлээ.","caution":"Сэтгэл хөдлөл дагалддаг: харамсал, гэнэтийн байдал, эсвэл санаа амрах.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-178","order":11,"bookLevel":5,"lesson":11,"lessonTitle":"관광과 안내","title":"(으)ㄴ/는데도","category":"Ерөнхий","role":"ч гэсэн, байтал.","analogy":"Монгол хэлний “... боловч”, “... ч гэсэн” тай адил.","structure":"A/V + (으)ㄴ/는데도","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"많이 잤는데도 피곤해요.","exampleMn":"Их унтсан ч ядарч байна.","caution":"Хүлээгдсэнээс эсрэг үр дүн.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-179","order":182,"bookLevel":5,"lesson":11,"lessonTitle":"관광과 안내","title":"(으)ㄴ/는 셈이다","category":"Ерөнхий","role":"тэгсэнтэй адил гэж үзэх.","analogy":"Монгол хэлний “... гэсэн үг”, “...-тай адил” тай ойролцоо.","structure":"V/A + (으)ㄴ/는 셈이다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"매일 만났으니 가족인 셈이에요.","exampleMn":"Өдөр бүр уулздаг болохоор гэр бүлтэй адил гэсэн үг.","caution":"Бодитой яг биш ч тооцож үзэхэд тийм.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-180","order":183,"bookLevel":5,"lesson":11,"lessonTitle":"관광과 안내","title":"여간 -지 않다","category":"Ерөнхий","role":"маш их, ер биш.","analogy":"Монгол хэлний “ер бусын их”, “үнэхээр” гэсэн хүчтэй утгатай.","structure":"여간 + A/V + 지 않다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"그 일이 여간 어렵지 않아요.","exampleMn":"Тэр ажил үнэхээр хэцүү.","caution":"Хэлбэр нь үгүйсгэл боловч утга нь хүчтэй эерэг/онцлол.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-181","order":12,"bookLevel":5,"lesson":12,"lessonTitle":"산업과 경제","title":"(으)ㅁ에 따라","category":"Ерөнхий","role":"...-ын дагуу/даган.","analogy":"Монгол хэлний “...-аас хамааран”, “... даган” тай ойролцоо.","structure":"V + (으)ㅁ에 따라","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"기술이 발전함에 따라 생활이 편리해졌어요.","exampleMn":"Технологи хөгжихийн хэрээр амьдрал тухтай болсон.","caution":"Бичгийн хэлэнд их хэрэглэгддэг.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-182","order":185,"bookLevel":5,"lesson":12,"lessonTitle":"산업과 경제","title":"만 해도","category":"Ерөнхий","role":"зөвхөн ... гэхэд л.","analogy":"Монгол хэлний “... гэхэд л” тай адил.","structure":"N + 만 해도","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"작년만 해도 이런 일이 없었어요.","exampleMn":"Өнгөрсөн жил гэхэд л ийм зүйл байгаагүй.","caution":"Жишээ болгон нэг зүйлийг онцолж харьцуулна.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-183","order":186,"bookLevel":5,"lesson":12,"lessonTitle":"산업과 경제","title":"는 대로","category":"Ерөнхий","role":"даруй, яг хийсний дагуу.","analogy":"Монгол хэлний “...-магц”, эсвэл “...-ын дагуу” тай ойролцоо.","structure":"V + 는 대로","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"도착하는 대로 연락하세요.","exampleMn":"Ирмэгцээ холбоо бариарай.","caution":"Контекстээс шалтгаалж “дагуу” эсвэл “даруй” утгатай.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-184","order":13,"bookLevel":5,"lesson":13,"lessonTitle":"한 국인의 사고방식","title":"(으)면서도","category":"Ерөнхий","role":"ингэж байгаа боловч.","analogy":"Монгол хэлний “... мөртлөө”, “... боловч” тай адил.","structure":"V/A + (으)면서도","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"알면서도 모르는 척했어요.","exampleMn":"Мэдэж байсан мөртлөө мэдэхгүй дүр эсгэсэн.","caution":"Хоёр зөрчилтэй үйл/байдлыг нэг субъект дээр хэлнэ.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-185","order":188,"bookLevel":5,"lesson":13,"lessonTitle":"한 국인의 사고방식","title":"기가 무섭게","category":"Ерөнхий","role":"...магц даруй.","analogy":"Монгол хэлний “...-магц”, “...-нгуут” тай адил.","structure":"V + 기가 무섭게","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"수업이 끝나기가 무섭게 나갔어요.","exampleMn":"Хичээл дуусмагц гарч явсан.","caution":"자마자 -аас арай хүчтэй, шууд болсон өнгөтэй.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-186","order":189,"bookLevel":5,"lesson":13,"lessonTitle":"한 국인의 사고방식","title":"아/어서 그런지","category":"Ерөнхий","role":"тийм болохоор ч юм уу.","analogy":"Монгол хэлний “... болохоор ч тэр үү” тай ойролцоо.","structure":"A/V + 아/어서 그런지","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"피곤해서 그런지 집중이 안 돼요.","exampleMn":"Ядарснаас ч тэр үү төвлөрч чадахгүй байна.","caution":"Шалтгааныг таамаг маягаар хэлнэ.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-187","order":14,"bookLevel":5,"lesson":14,"lessonTitle":"한 국인의 일생","title":"(ㄴ/는)다면서요?","category":"Ерөнхий","role":"сонссон зүйлээ батлах.","analogy":"Монгол хэлний “... гэсэн биз дээ?”, “... гэл үү?” тай ойролцоо.","structure":"V/A + ㄴ/는다면서요?","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"다음 달에 결혼한다면서요?","exampleMn":"Ирэх сард гэрлэнэ гэсэн биз дээ?","caution":"Сонссон мэдээллээ эелдэгээр шалгана.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-188","order":191,"bookLevel":5,"lesson":14,"lessonTitle":"한 국인의 일생","title":"게 마련이다","category":"Ерөнхий","role":"зайлшгүй тэгдэг жамтай.","analogy":"Монгол хэлний “... байх нь жам”, “... л байдаг” тай ойролцоо.","structure":"V/A + 게 마련이다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"노력하면 결과가 나오게 마련이에요.","exampleMn":"Хичээвэл үр дүн гардаг жамтай.","caution":"Ерөнхий зүй тогтол, inevitability.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-189","order":192,"bookLevel":5,"lesson":14,"lessonTitle":"한 국인의 일생","title":"조차","category":"Ерөнхий","role":"бүр ... хүртэл.","analogy":"Монгол хэлний “бүр ... ч”, “... хүртэл” тай адил.","structure":"N + 조차","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"이름조차 기억이 안 나요.","exampleMn":"Нэрийг нь хүртэл санахгүй байна.","caution":"Ихэнхдээ сөрөг, гайхсан өнгөтэй.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-190","order":15,"bookLevel":5,"lesson":15,"lessonTitle":"한 국 유학","title":"거든","category":"Нөхцөл","role":"нөхцөл эсвэл тайлбарын суурь.","analogy":"Монгол хэлний “... бол”, “... шүү дээ” тай ойролцоо.","structure":"V/A + 거든","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “нөхцөл” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"시간이 있거든 전화해 주세요.","exampleMn":"Зав байвал залгаарай.","caution":"Өгүүлбэрийн төгсгөлд ирвэл тайлбарлах өнгө: 제가 좀 바쁘거든요 .","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-191","order":194,"bookLevel":5,"lesson":15,"lessonTitle":"한 국 유학","title":"아/어 내다","category":"Ерөнхий","role":"эцэст нь хийж чадсан.","analogy":"Монгол хэлний “...-ж чадлаа”, “аравчаад гаргалаа” тай ойролцоо.","structure":"V + 아/어 내다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"어려운 일을 해냈어요.","exampleMn":"Хэцүү ажлыг хийж чадлаа.","caution":"Бэрхшээлийг давж үр дүнд хүрсэн мэдрэмжтэй.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-192","order":195,"bookLevel":5,"lesson":15,"lessonTitle":"한 국 유학","title":"(이)라든가","category":"Ерөнхий","role":"гэх мэт жишээ.","analogy":"Монгол хэлний “... гэх мэт”, “... ч юм уу” тай адил.","structure":"N + (이)라든가","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"김치라든가 불고기 같은 음식을 좋아해요.","exampleMn":"Кимчи, пүлгуги гэх мэт хоолонд дуртай.","caution":"Жишээ жагсаахад хэрэглэнэ. Дэвтэр 6","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-193","order":1,"bookLevel":6,"lesson":1,"lessonTitle":"가족제도","title":"(으)ㄴ 나머지","category":"Ерөнхий","role":"хэт ...-снээс болоод.","analogy":"Монгол хэлний “хэт ...-сандаа” тай ойролцоо.","structure":"V/A + (으)ㄴ 나머지","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"너무 놀란 나머지 말을 못 했어요.","exampleMn":"Хэт гайхсандаа үг хэлж чадсангүй.","caution":"Хэтэрхий хүчтэй шалтгаанаас үр дүн гарна.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-194","order":197,"bookLevel":6,"lesson":1,"lessonTitle":"가족제도","title":"기 짝이 없다","category":"Ерөнхий","role":"туйлын, үгээр хэлэхийн аргагүй.","analogy":"Монгол хэлний “туйлын ...”, “маш ...” гэсэн хүчтэй үнэлгээтэй.","structure":"A + 기 짝이 없다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"그 행동은 무례하기 짝이 없어요.","exampleMn":"Тэр үйлдэл туйлын бүдүүлэг.","caution":"Ихэвчлэн сөрөг үнэлгээнд хэрэглэгдэнэ.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-195","order":199,"bookLevel":6,"lesson":1,"lessonTitle":"가족제도","title":"더러/보고","category":"Ерөнхий","role":"хэн нэгэнд хэлэх/захих чиг.","analogy":"Монгол хэлний “...-д/руу хэлэх” тай ойролцоо.","structure":"N + 더러/보고","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"친구더러 먼저 가라고 했어요.","exampleMn":"Найздаа түрүүлж яв гэж хэлсэн.","caution":"Ярианы хэлэнд, хүн/амьтанд чиглэнэ.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-196","order":2,"bookLevel":6,"lesson":2,"lessonTitle":"과학과 미래","title":"고자","category":"Зорилго","role":"албан зорилго.","analogy":"Монгол хэлний “...-хын тулд”, “...-х зорилгоор” тай адил.","structure":"V + 고자","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “зорилго” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"한국어를 배우고자 한국에 왔습니다.","exampleMn":"Солонгос хэл сурах зорилгоор Солонгост ирсэн.","caution":"Бичгийн/албан хэл; - 려고 하다 -аас албан.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-197","order":201,"bookLevel":6,"lesson":2,"lessonTitle":"과학과 미래","title":"(ㄴ/는)다기에","category":"Шалтгаан","role":"сонссон шалтгаанаар.","analogy":"Монгол хэлний “... гэж сонсоод”, “... гэсэн болохоор” тай ойролцоо.","structure":"V/A + ㄴ/는다기에","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “шалтгаан” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"비가 온다기에 우산을 가져왔어요.","exampleMn":"Бороо орно гэсэн болохоор шүхэр авчирсан.","caution":"Сонссон мэдээлэл үйлдлийн шалтгаан болно.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-198","order":202,"bookLevel":6,"lesson":2,"lessonTitle":"과학과 미래","title":"마저","category":"Ерөнхий","role":"үлдсэн/хамгийн сүүлчийн зүйл хүртэл.","analogy":"Монгол хэлний “бүр ... хүртэл”, “... ч хүртэл” тай ойролцоо.","structure":"N + 마저","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"친구마저 나를 믿지 않았어요.","exampleMn":"Найз хүртэл надад итгээгүй.","caution":"Сөрөг, харамссан өнгө ихтэй.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-199","order":203,"bookLevel":6,"lesson":2,"lessonTitle":"과학과 미래","title":"(으)ㄴ 탓","category":"Шалтгаан","role":"сөрөг шалтгаан.","analogy":"Монгол хэлний “...-аас болж”, “...-ын буруугаас” тай адил.","structure":"A/V + (으)ㄴ/는 탓에, N 탓에","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “шалтгаан” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"날씨가 나쁜 탓에 여행을 취소했어요.","exampleMn":"Цаг агаар муугаас болж аяллаа цуцалсан.","caution":"덕분에 = сайн үр дүн; 탓에 = муу үр дүн.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-200","order":3,"bookLevel":6,"lesson":3,"lessonTitle":"한국어와 사회","title":"(으)ㄹ 겸","category":"Зорилго","role":"давхар зорилгоор.","analogy":"Монгол хэлний “... ч хийх, ... ч хийхээр”, “далимд” тай ойролцоо.","structure":"V + (으)ㄹ 겸","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “зорилго” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"친구도 만날 겸 서울에 갔어요.","exampleMn":"Найзтайгаа ч уулзах, Сөүл ч үзэхээр явсан.","caution":"Нэг үйлдлээр хоёр зорилго гүйцэтгэх.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-201","order":205,"bookLevel":6,"lesson":3,"lessonTitle":"한국어와 사회","title":"고말고요","category":"Ерөнхий","role":"мэдээж тийм.","analogy":"Монгол хэлний “тэгэлгүй яах вэ”, “мэдээж” тай адил.","structure":"V/A + 고말고요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"물론 도와드리고말고요.","exampleMn":"Мэдээж туслалгүй яах вэ.","caution":"Хүчтэй зөвшөөрөл, баталгаа.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-202","order":207,"bookLevel":6,"lesson":3,"lessonTitle":"한국어와 사회","title":"더라도","category":"Ерөнхий","role":"ч гэсэн, байсан ч.","analogy":"Монгол хэлний “... ч гэсэн”, “... байсан ч” тай адил.","structure":"V/A + 더라도","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"힘들더라도 포기하지 마세요.","exampleMn":"Хэцүү байсан ч битгий бууж өг.","caution":"Таамаг эсрэг нөхцөл; үр дүн өөрчлөгдөхгүй.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-203","order":4,"bookLevel":6,"lesson":4,"lessonTitle":"한국문학","title":"고서","category":"Ерөнхий","role":"хийсний дараа / хийчихээд.","analogy":"Монгол хэлний “...-сны дараа”, “...-чихаад” тай ойролцоо.","structure":"V + 고서","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"사실을 알고서 마음이 바뀌었어요.","exampleMn":"Үнэнийг мэдсэний дараа бодол өөрчлөгдсөн.","caution":"Дараалал болон үр дагаврыг тодруулна.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-204","order":209,"bookLevel":6,"lesson":4,"lessonTitle":"한국문학","title":"고요","category":"Ерөнхий","role":"нэмж хэлэх, зөөлөн төгсгөх.","analogy":"Монгол хэлний “бас”, “тэгээд”, зөөлөн нэмэлт тайлбартай ойролцоо.","structure":"V/A + 고요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"저는 몽골 사람이고요, 한국어를 공부해요.","exampleMn":"Би монгол хүн, бас солонгос хэл сурдаг.","caution":"Ярианд өгүүлбэрийг зөөлөн үргэлжлүүлэхэд хэрэглэнэ.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-205","order":210,"bookLevel":6,"lesson":4,"lessonTitle":"한국문학","title":"던가요?","category":"Ерөнхий","role":"санахгүй/зөөлөн асуух.","analogy":"Монгол хэлний “... бил үү?”, “... байсан бил үү?” тай адил.","structure":"V/A + 던가요?","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"그 사람이 언제 온다고 했던가요?","exampleMn":"Тэр хүн хэзээ ирнэ гэсэн билээ?","caution":"Өнгөрсөн мэдээллийг эргэн санах асуулт.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-206","order":211,"bookLevel":6,"lesson":4,"lessonTitle":"한국문학","title":"(이)나 (이)나 할 것 없이","category":"Ерөнхий","role":"ялгаагүй бүгд.","analogy":"Монгол хэлний “... ч тэр ... ч тэр ялгаагүй” тай адил.","structure":"N + (이)나 N + (이)나 할 것 없이","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"어른이나 아이나 할 것 없이 모두 좋아해요.","exampleMn":"Том ч бай, хүүхэд ч бай бүгд дуртай.","caution":"Бүлэг ялгалгүй хамруулах.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-207","order":5,"bookLevel":6,"lesson":5,"lessonTitle":"한국의 문화유산","title":"기는커녕","category":"Ерөнхий","role":"байтугай, битгий хэл.","analogy":"Монгол хэлний “... байтугай”, “... ч үгүй” тай адил.","structure":"V + 기는커녕 / N + 은/는커녕","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"밥은커녕 물도 못 마셨어요.","exampleMn":"Хоол байтугай ус ч ууж чадсангүй.","caution":"Хүлээгдсэнээс бүр доогуур байдал.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-208","order":213,"bookLevel":6,"lesson":5,"lessonTitle":"한국의 문화유산","title":"(으)니만큼","category":"Ерөнхий","role":"... болохоор, ... хэмжээгээр.","analogy":"Монгол хэлний “... учраас”, “... болохоор” тай ойролцоо.","structure":"V/A + (으)니만큼","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"열심히 준비했으니만큼 좋은 결과가 있을 거예요.","exampleMn":"Сайн бэлдсэн болохоор сайн үр дүн гарах байх.","caution":"Шалтгаан/үндэслэлийг хүчтэй тавина.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-209","order":214,"bookLevel":6,"lesson":5,"lessonTitle":"한국의 문화유산","title":"(으)ㄹ 따름이다","category":"Ерөнхий","role":"зөвхөн тэгэх л.","analogy":"Монгол хэлний “... л юм”, “... төдий” тай ойролцоо.","structure":"V/A + (으)ㄹ 따름이다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"도와주셔서 감사할 따름입니다.","exampleMn":"Тусалсанд тань зөвхөн талархах л байна.","caution":"Бичгийн/албан, даруухан илэрхийлэл.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-210","order":215,"bookLevel":6,"lesson":5,"lessonTitle":"한국의 문화유산","title":"는 수가 있다.","category":"Ерөнхий","role":"тийм тохиолдол гарч болно.","analogy":"Монгол хэлний “... тохиолдож болно”, “... магадгүй” тай ойролцоо.","structure":"V + 는 수가 있다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"방심하면 실수하는 수가 있어요.","exampleMn":"Анхаарал сулрахад алдах тохиолдол гарч болно.","caution":"Боломжит сөрөг/болгоомжлолын утгатай.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-211","order":6,"bookLevel":6,"lesson":6,"lessonTitle":"국제사회","title":"(으)ㄹ 법하다","category":"Ерөнхий","role":"тэгэх магадлалтай/зүйтэй.","analogy":"Монгол хэлний “... байх магадлалтай”, “...-маар” тай ойролцоо.","structure":"V/A + (으)ㄹ 법하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"이제 도착할 법한데 아직 안 왔어요.","exampleMn":"Одоо ирэхээр болсон баймаар, гэхдээ ирээгүй.","caution":"Нөхцлөөс харахад тийм байх ёстой мэт.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-212","order":217,"bookLevel":6,"lesson":6,"lessonTitle":"국제사회","title":"(이)나마","category":"Ерөнхий","role":"ядаж боловч.","analogy":"Монгол хэлний “ядаж ... ч болов” тай адил.","structure":"N + (이)나마","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"작은 도움이나마 드리고 싶어요.","exampleMn":"Жаахан ч гэсэн тус хүргэмээр байна.","caution":"Даруухан, хангалтгүй ч гэсэн санал болгох.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-213","order":218,"bookLevel":6,"lesson":6,"lessonTitle":"국제사회","title":"더라고요","category":"Таамаг/ажиглалт","role":"өөрийн ажиглалтаа эелдэгээр хэлэх.","analogy":"Монгол хэлний “... юм билээ”, “... байсан шүү” тай ойролцоо.","structure":"V/A + 더라고요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “таамаг/ажиглалт” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"서울은 생각보다 복잡하더라고요.","exampleMn":"Сөүл бодсоноос төвөгтэй юм билээ.","caution":"Өөрөө харж мэдсэн зүйлд хэрэглэнэ.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-214","order":219,"bookLevel":6,"lesson":6,"lessonTitle":"국제사회","title":"(으)련마는","category":"Ерөнхий","role":"... байх байсан ч.","analogy":"Монгол хэлний “... байх сан, гэвч” тай ойролцоо.","structure":"V/A + (으)련마는","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"시간이 있으면 도와주련마는 지금은 어려워요.","exampleMn":"Цаг байсан бол туслахсан, гэвч одоо хэцүү.","caution":"Уянгын/бичгийн эсрэгцэл.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-215","order":7,"bookLevel":6,"lesson":7,"lessonTitle":"현대사회와 스포츠","title":"기 십상이다","category":"Ерөнхий","role":"амархан тэгдэг, тэгэх магадлал өндөр.","analogy":"Монгол хэлний “...-х нь элбэг”, “...-хдаа амархан” тай ойролцоо.","structure":"V + 기 십상이다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"서두르면 실수하기 십상이에요.","exampleMn":"Яарвал алдах нь элбэг.","caution":"Ихэвчлэн сөрөг үр дагавартай.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-216","order":221,"bookLevel":6,"lesson":7,"lessonTitle":"현대사회와 스포츠","title":"(으)ㄹ뿐더러","category":"Ерөнхий","role":"төдийгүй бас.","analogy":"Монгол хэлний “... төдийгүй”, “бас” тай адил.","structure":"V/A + (으)ㄹ뿐더러","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"그는 성실할뿐더러 친절해요.","exampleMn":"Тэр нягт нямбай төдийгүй эелдэг.","caution":"뿐만 아니라 -тай ижил, бичгийн өнгөтэй.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-217","order":222,"bookLevel":6,"lesson":7,"lessonTitle":"현대사회와 스포츠","title":"(ㄴ/는)다거나","category":"Боломж","role":"... гэх мэт боломж/жишээ.","analogy":"Монгол хэлний “... ч юм уу”, “... гэх мэт” тай ойролцоо.","structure":"V/A + ㄴ/는다거나","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “боломж” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"산책을 한다거나 음악을 들으면 기분이 좋아져요.","exampleMn":"Алхах ч юм уу хөгжим сонсвол сэтгэл сайхан болдог.","caution":"Жишээ сонголтуудыг сул жагсаана.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-218","order":223,"bookLevel":6,"lesson":7,"lessonTitle":"현대사회와 스포츠","title":"(으)ㄹ지라도/(으)ㄹ지언정","category":"Ерөнхий","role":"хэдий ... ч.","analogy":"Монгол хэлний “... ч гэсэн”, “... байсан ч” тай адил.","structure":"V/A + (으)ㄹ지라도 / (으)ㄹ지언정","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"힘들지라도 포기하지 않겠습니다.","exampleMn":"Хэцүү байсан ч бууж өгөхгүй.","caution":"Албан/бичгийн хүчтэй эсрэг нөхцөл.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-219","order":8,"bookLevel":6,"lesson":8,"lessonTitle":"정치제도","title":"(으)ㄹ 바에야","category":"Ерөнхий","role":"тэгэхийн оронд.","analogy":"Монгол хэлний “...-снаас”, “...-хаар бол” тай ойролцоо.","structure":"V + (으)ㄹ 바에야","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"포기할 바에야 처음부터 시작하지 마세요.","exampleMn":"Бууж өгөх гэж байгаа бол эхнээс нь битгий эхэл.","caution":"Нэг муу сонголтоос нөгөөг илүүд үзэх.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-220","order":226,"bookLevel":6,"lesson":8,"lessonTitle":"정치제도","title":"고 들다","category":"Ерөнхий","role":"зөрүүдлэн хийх гэж байх.","analogy":"Монгол хэлний “... гэж зүтгэх”, “... гээд дайрах” тай адил.","structure":"V + 고 들다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"아이가 혼자 가겠다고 들어요.","exampleMn":"Хүүхэд ганцаараа явна гэж зүтгэж байна.","caution":"Сөрөг/зөрүүд өнгө ихтэй.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-221","order":227,"bookLevel":6,"lesson":8,"lessonTitle":"정치제도","title":"(ㄴ/는)다마는","category":"Ерөнхий","role":"... боловч.","analogy":"Монгол хэлний “... боловч/гэвч” тай адил.","structure":"V/A + ㄴ/는다마는","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"이해는 한다마는 동의할 수는 없어요.","exampleMn":"Ойлгож байгаа ч зөвшөөрч чадахгүй.","caution":"Бичгийн/хуучиндуу эсрэгцэл.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-222","order":9,"bookLevel":6,"lesson":9,"lessonTitle":"생활과 경제","title":"(으)ㄹ락 말락 하다","category":"Ерөнхий","role":"... гэж байгаа юм шиг байснаа үгүй.","analogy":"Монгол хэлний “...х гээд байх”, “...х дөхөөд болих” тай ойролцоо.","structure":"V + (으)ㄹ락 말락 하다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"비가 올락 말락 해요.","exampleMn":"Бороо орох гээд байх шиг байна.","caution":"Болох эсэх нь зааг дээр.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-223","order":229,"bookLevel":6,"lesson":9,"lessonTitle":"생활과 경제","title":"(으)ㄹ 리가 없다","category":"Боломж","role":"тийм байх ёсгүй/боломжгүй.","analogy":"Монгол хэлний “... байх учиргүй”, “... боломжгүй” тай адил.","structure":"V/A + (으)ㄹ 리가 없다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “боломж” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"그 사람이 거짓말할 리가 없어요.","exampleMn":"Тэр хүн худлаа хэлэх учиргүй.","caution":"Өгүүлэгч итгэлтэй үгүйсгэнэ.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-224","order":230,"bookLevel":6,"lesson":9,"lessonTitle":"생활과 경제","title":"(으)ㄴ/는 마당에","category":"Нөхцөл","role":"ийм нөхцөлд байхад.","analogy":"Монгол хэлний “... байгаа нөхцөлд”, “... байхад” тай ойролцоо.","structure":"V/A + (으)ㄴ/는 마당에","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “нөхцөл” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"시간도 없는 마당에 회의를 또 하자고요?","exampleMn":"Цаг ч байхгүй байхад дахин хуралдая гэж үү?","caution":"Нөхцөл байдлыг суурь болгон эсэргүүцэх/дүгнэх.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-225","order":231,"bookLevel":6,"lesson":9,"lessonTitle":"생활과 경제","title":"느니 차라리","category":"Ерөнхий","role":"...снаас дээр нь.","analogy":"Монгол хэлний “...снаас харин ...” тай адил.","structure":"V + 느니 차라리","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"기다리느니 차라리 걸어가겠어요.","exampleMn":"Хүлээснээс харин алхаж явъя.","caution":"Хоёр муу сонголтоос арай дээрийг сонгоно.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-226","order":10,"bookLevel":6,"lesson":10,"lessonTitle":"한국의 역사","title":"(으)랴 -(으)랴","category":"Ерөнхий","role":"олон ажил зэрэг хийх.","analogy":"Монгол хэлний “... ч хийх, ... ч хийх гээд” тай ойролцоо.","structure":"V + (으)랴 V + (으)랴","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"일하랴 공부하랴 정말 바빠요.","exampleMn":"Ажил ч хийх, хичээл ч хийх гээд их завгүй.","caution":"Олон зүйл зэрэгцэн ачаалал үүсгэх.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-227","order":233,"bookLevel":6,"lesson":10,"lessonTitle":"한국의 역사","title":"기 일쑤다","category":"Ерөнхий","role":"байнга тэгдэг, тэгэх нь олон.","analogy":"Монгол хэлний “...-х нь олон”, “байнга ...-даг” тай ойролцоо.","structure":"V + 기 일쑤다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"급하게 하면 실수하기 일쑤예요.","exampleMn":"Яарвал алдах нь олон.","caution":"Давтагддаг сөрөг зуршил/үр дагавар.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-228","order":234,"bookLevel":6,"lesson":10,"lessonTitle":"한국의 역사","title":"(ㄴ/는)다는 점에서","category":"Ерөнхий","role":"... гэсэн талаасаа.","analogy":"Монгол хэлний “... гэдэг талаасаа”, “... гэсэн өнцгөөс” тай адил.","structure":"V/A + ㄴ/는다는 점에서","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"서로 돕는다는 점에서 의미가 있어요.","exampleMn":"Бие биедээ тусалдаг гэдэг талаасаа утга учиртай.","caution":"Дүгнэлт хийх шалгуур/өнцгийг заана.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-229","order":235,"bookLevel":6,"lesson":10,"lessonTitle":"한국의 역사","title":"(으)로 말미암아","category":"Ерөнхий","role":"улмаас, шалтгаалан.","analogy":"Монгол хэлний “...-ын улмаас”, “...-аас болж” тай адил.","structure":"N + (으)로 말미암아","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"전쟁으로 말미암아 많은 사람이 고통을 겪었어요.","exampleMn":"Дайны улмаас олон хүн зовсон.","caution":"Албан/бичгийн хэл, ихэвчлэн хүнд сэдэв.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-230","order":11,"bookLevel":6,"lesson":11,"lessonTitle":"현대의 의학","title":"(으)ㄴ들","category":"Ерөнхий","role":"хэдий ... ч ямар нэмэр.","analogy":"Монгол хэлний “...лаа гээд”, “...сан ч” тай ойролцоо.","structure":"V/A + (으)ㄴ들","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"후회한들 무슨 소용이 있겠어요?","exampleMn":"Харамслаа гээд ямар хэрэг байх вэ?","caution":"Хийсэн ч үр дүн өөрчлөгдөхгүй гэсэн өнгө.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-231","order":237,"bookLevel":6,"lesson":11,"lessonTitle":"현대의 의학","title":"(으)면 몰라도","category":"Ерөнхий","role":"... бол өөр хэрэг, харин.","analogy":"Монгол хэлний “... бол яахав, харин ...” тай адил.","structure":"V/A + (으)면 몰라도","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"혼자라면 몰라도 아이들과는 힘들어요.","exampleMn":"Ганцаараа бол яахав, хүүхдүүдтэй бол хэцүү.","caution":"Нэг нөхцөлд зөвшөөрөөд өөр нөхцөлд үгүйсгэнэ.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-232","order":238,"bookLevel":6,"lesson":11,"lessonTitle":"현대의 의학","title":"길래","category":"Шалтгаан","role":"яагаад тэгсэн гэх шалтгаан.","analogy":"Монгол хэлний “... гэж/болохоор”, “яасан болоод” тай ойролцоо.","structure":"V/A + 길래","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “шалтгаан” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"무슨 일이 있길래 그렇게 급해요?","exampleMn":"Юу болсон болоод тэгтлээ яараа вэ?","caution":"Ярианы хэл, шалтгаан асуух/тайлбарлах.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-233","order":239,"bookLevel":6,"lesson":11,"lessonTitle":"현대의 의학","title":"기나 하면","category":"Ерөнхий","role":"ядаж ... бол.","analogy":"Монгол хэлний “ядаж ... бол” тай ойролцоо.","structure":"V + 기나 하면","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"연락이라도 오기나 하면 좋겠어요.","exampleMn":"Ядаж холбоо баривал сайнсан.","caution":"Хүлээлт бага, хүсэлтэй өнгө.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-234","order":12,"bookLevel":6,"lesson":12,"lessonTitle":"인간과 자연","title":"(으)나 마나","category":"Ерөнхий","role":"хийсэн ч хийгээгүй ч адил.","analogy":"Монгол хэлний “...сан ч нэмэргүй”, “...ад ч хэрэггүй” тай адил.","structure":"V + (으)나 마나","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"물어보나 마나 거절할 거예요.","exampleMn":"Асуусан ч татгалзах нь ойлгомжтой.","caution":"Үр дүн нь тодорхой тул хийх хэрэггүй мэт.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-235","order":241,"bookLevel":6,"lesson":12,"lessonTitle":"인간과 자연","title":"건마는","category":"Ерөнхий","role":"гэвч, боловч.","analogy":"Монгол хэлний “гэвч/боловч” тай адил.","structure":"V/A + 건마는","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"알고는 있건마는 실천하기 어려워요.","exampleMn":"Мэдэж байгаа боловч хэрэгжүүлэх хэцүү.","caution":"Бичгийн, уран найруулгын өнгөтэй.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-236","order":242,"bookLevel":6,"lesson":12,"lessonTitle":"인간과 자연","title":"은/는 고사하고","category":"Ерөнхий","role":"байтугай.","analogy":"Монгол хэлний “... байтугай” тай адил.","structure":"N + 은/는 고사하고","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"여행은 고사하고 쉴 시간도 없어요.","exampleMn":"Аялал байтугай амрах цаг ч алга.","caution":"Том зүйлийг орхиод бага зүйл ч боломжгүйг хэлнэ.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-237","order":243,"bookLevel":6,"lesson":12,"lessonTitle":"인간과 자연","title":"거니와","category":"Ерөнхий","role":"төдийгүй, бас.","analogy":"Монгол хэлний “... төдийгүй”, “бас” тай адил.","structure":"V/A + 거니와","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"그는 성실하거니와 실력도 뛰어나요.","exampleMn":"Тэр нягт нямбай төдийгүй чадвар ч өндөр.","caution":"Бичгийн/албан холбоос.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-238","order":13,"bookLevel":6,"lesson":13,"lessonTitle":"정보와 통신","title":"(으)ㄹ 줄이야","category":"Ерөнхий","role":"тэгнэ гэж огт бодоогүй.","analogy":"Монгол хэлний “... гэж бодсонгүй”, “... гэж үү дээ” тай ойролцоо.","structure":"V + (으)ㄹ 줄이야","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"그가 우승할 줄이야 몰랐어요.","exampleMn":"Тэр түрүүлнэ гэж бодсонгүй.","caution":"Гайхал, санаандгүй үр дүн.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-239","order":245,"bookLevel":6,"lesson":13,"lessonTitle":"정보와 통신","title":"기 마련이다","category":"Ерөнхий","role":"зайлшгүй тэгдэг жамтай.","analogy":"Монгол хэлний “... байдаг жамтай” тай адил.","structure":"V/A + 기 마련이다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"사람은 누구나 실수하기 마련이에요.","exampleMn":"Хүн бүр алдах нь жам.","caution":"Ерөнхий зүй тогтол.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-240","order":246,"bookLevel":6,"lesson":13,"lessonTitle":"정보와 통신","title":"(으)ㄹ래야 -(으)ㄹ 수 없다","category":"Ерөнхий","role":"хичээсэн ч чадахгүй.","analogy":"Монгол хэлний “...х гээд ч ...ж чадахгүй” тай адил.","structure":"V + (으)ㄹ래야 V + (으)ㄹ 수 없다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"너무 바빠서 쉴래야 쉴 수가 없어요.","exampleMn":"Хэт завгүй болохоор амаръя гээд ч амарч чадахгүй.","caution":"Санаа байвч боломжгүй.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-241","order":247,"bookLevel":6,"lesson":13,"lessonTitle":"정보와 통신","title":"도 -(으)려니와","category":"Ерөнхий","role":"... ч мөн, дээрээс нь.","analogy":"Монгол хэлний “... ч тийм, бас ...” тай ойролцоо.","structure":"N도/V도 + (으)려니와","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"가격도 비싸려니와 품질도 좋지 않아요.","exampleMn":"Үнэ нь ч өндөр, дээрээс нь чанар нь ч сайн биш.","caution":"Хоёр шалтгааныг зэрэг нэмнэ.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-242","order":14,"bookLevel":6,"lesson":14,"lessonTitle":"현대사회의 문제","title":"을/를 막론하고","category":"Ерөнхий","role":"үл харгалзан.","analogy":"Монгол хэлний “... үл харгалзан”, “... ялгалгүй” тай адил.","structure":"N + 을/를 막론하고","usage":"Нэр үг дээр залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"나이를 막론하고 모두 참여할 수 있어요.","exampleMn":"Нас үл харгалзан бүгд оролцож болно.","caution":"Албан, нийтэд хамруулах хэлбэр.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-243","order":249,"bookLevel":6,"lesson":14,"lessonTitle":"현대사회의 문제","title":"(으)리라","category":"Таамаг/ажиглалт","role":"бичгийн таамаг/итгэл.","analogy":"Монгол хэлний “... гэж итгэнэ”, “... байх болно” тай ойролцоо.","structure":"V/A + (으)리라","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “таамаг/ажиглалт” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"좋은 결과가 있으리라 믿습니다.","exampleMn":"Сайн үр дүн гарна гэж итгэж байна.","caution":"Албан/бичгийн, уран найруулгад хэрэглэнэ.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-244","order":250,"bookLevel":6,"lesson":14,"lessonTitle":"현대사회의 문제","title":"아/어 봤자","category":"Ерөнхий","role":"оролдсон ч үр дүнгүй.","analogy":"Монгол хэлний “...аад ч нэмэргүй” тай адил.","structure":"V + 아/어 봤자","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"지금 가 봤자 늦었어요.","exampleMn":"Одоо очоод ч оройтсон.","caution":"Хийсэн ч хүссэн үр дүн гарахгүй.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-245","order":251,"bookLevel":6,"lesson":14,"lessonTitle":"현대사회의 문제","title":"(으)ㄹ망정","category":"Ерөнхий","role":"хэдий ... ч.","analogy":"Монгол хэлний “... боловч”, “... ч гэсэн” тай ойролцоо.","structure":"V/A + (으)ㄹ망정","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"가난할망정 부끄럽지 않아요.","exampleMn":"Ядуу ч ичгүүртэй биш.","caution":"Бичгийн/албан эсрэгцэл.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-246","order":15,"bookLevel":6,"lesson":15,"lessonTitle":"취업과 직장 생활","title":"기 나름이다","category":"Ерөнхий","role":"...-аас хамаарна.","analogy":"Монгол хэлний “...-аас шалтгаална/хамаарна” тай адил.","structure":"V + 기 나름이다","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"성공은 노력하기 나름이에요.","exampleMn":"Амжилт хичээхээс хамаарна.","caution":"Үр дүн нь тухайн үйлдлийн чанараас шалтгаална.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-247","order":253,"bookLevel":6,"lesson":15,"lessonTitle":"취업과 직장 생활","title":"는 김에","category":"Ерөнхий","role":"далимд.","analogy":"Монгол хэлний “...-сний далимд” тай адил.","structure":"V + 는 김에","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"마트에 가는 김에 우유도 사 오세요.","exampleMn":"Дэлгүүр явахын далимд сүү аваад ирээрэй.","caution":"Нэг үйлдэл хийх зуураа өөр зүйлийг хамт хийх.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-248","order":254,"bookLevel":6,"lesson":15,"lessonTitle":"취업과 직장 생활","title":"는 둥 마는 둥","category":"Ерөнхий","role":"хийсэн нэртэй, дутуу.","analogy":"Монгол хэлний “...сан ч юм шиг үгүй ч юм шиг”, “хагас дутуу” тай ойролцоо.","structure":"V + 는 둥 마는 둥","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. Өмнөх болон дараах өгүүлбэрийн утгын холбоог заавал хамтад нь харна.","exampleKo":"아침을 먹는 둥 마는 둥 하고 나왔어요.","exampleMn":"Өглөөний цайгаа идсэн ч юм шиг үгүй ч юм шиг гараад ирсэн.","caution":"Үйлдэл бүрэн/чин сэтгэлээсээ болоогүй.","stage":"Гүнзгий шат","source":"Explained MN Grammar"},{"id":"ko-explained-249","order":255,"bookLevel":6,"lesson":15,"lessonTitle":"취업과 직장 생활","title":"(으)ㄴ/는걸요","category":"Ерөнхий","role":"зөөлөн эсэргүүцэл/тайлбар.","analogy":"Монгол хэлний “... шүү дээ”, “харин ... юм байна” тай ойролцоо.","structure":"V/A + (으)ㄴ/는걸요","usage":"Үйл үг/тэмдэг үйл үгийн үндсэнд залгана. Өгүүлбэрт энэ хэлбэр нь “ерөнхий” үүрэг гүйцэтгэнэ. эгшгээр төгсвөл эхний хэлбэр, гийгүүлэгчээр төгсвөл ( 으 ) орсон хэлбэрийг сонгоно","exampleKo":"생각보다 어려운걸요.","exampleMn":"Бодсоноос хэцүү юм байна шүү дээ.","caution":"Өгүүлэгчийн шинэ мэдрэмж эсвэл зөөлөн залруулга.","stage":"Гүнзгий шат","source":"Explained MN Grammar"}]};
